import subprocess, sys, itertools, json, os, re, functools, collections
cache = '/tmp/pw_cache.json'
db = json.load(open(cache)) if os.path.exists(cache) else {}
def run(css):
    p = subprocess.run(['/workspace/executable'], input=css.encode(), capture_output=True)
    if p.returncode != 0: return None
    return p.stdout.decode()
def decl_order(css):
    out = run(css)
    if out is None: return None
    res = []
    for line in out.split('\n'):
        m = re.match(r'^\s*((-{1,2})?[a-zA-Z-]+)\s*:', line)
        if m: res.append(m.group(1))
    return res
def cmp2(a,b):
    k = a+'|'+b
    if k in db: return db[k]
    o1 = decl_order('a{%s;%s}' % (a,b))
    o2 = decl_order('a{%s;%s}' % (b,a))
    r = 0 if o1==o2 else (-1 if o1 and o1[0]==a else 1)
    db[k]=r; json.dump(db, open(cache,'w'))
    return r
props = sys.argv[1].split(',')
lt = collections.defaultdict(set); eq = collections.defaultdict(set)
for a,b in itertools.combinations(props,2):
    r = cmp2(a,b)
    if r<0: lt[a].add(b)
    elif r>0: lt[b].add(a)
    else: eq[a].add(b); eq[b].add(a)
seen=set(); groups=[]
for p in props:
    if p in seen: continue
    c = frozenset(eq[p]|{p})
    for q in c: seen.add(q)
    groups.append(c)
def cc(g1,g2):
    x=next(iter(g1)); y=next(iter(g2))
    if y in lt[x]: return -1
    if x in lt[y]: return 1
    return 0
groups.sort(key=functools.cmp_to_key(cc))
for g in groups:
    print('|'.join(sorted(g)))
