import subprocess, re
EXE='/workspace/executable'
def run(css, extra=None):
    p = subprocess.run([EXE]+(extra or []), input=css.encode(), capture_output=True)
    return p.stdout.decode(), p.returncode
def decls(out):
    return [m.group(1) for l in out.split('\n') if (m:=re.match(r'^\s*((-{1,2})?[a-zA-Z0-9-]+)\s*:', l))]
def cmp_props(a, b, va='1px', vb='2px'):
    """a,b are property names; returns 'LT' if a ranks before b, 'GT' if after, 'EQ' if tie."""
    o1 = decls(run('a{%s:%s;%s:%s}' % (a,va,b,vb))[0])
    o2 = decls(run('a{%s:%s;%s:%s}' % (b,vb,a,va))[0])
    if len(o1)!=2 or len(o2)!=2: return 'ERR'
    if o1[0]==a and o2[0]==a: return 'LT'
    if o1[0]==b and o2[0]==b: return 'GT'
    return 'EQ'
def order_of(css, extra=None):
    return decls(run(css, extra)[0])
def ins_sort(items, rel):
    arr=list(items)
    for i in range(1,len(arr)):
        j=i
        while j>0 and rel(arr[j-1],arr[j])=='GT':
            arr[j-1],arr[j]=arr[j],arr[j-1]; j-=1
    return arr
