{"command": "cd /workspace && python3 -c "
import sys; sys.path.insert(0,'/tmp')
from lib import *
import itertools
props=['color','opacity','z-index','width','box-shadow']
rel={}
for a,b in itertools.combinations(props,2):
    r=cmp_props(a,b,'red','2px')
    rel[(a,b)]=r; rel[(b,a)]=r
    print('%-12s %-12s %s' % (a,b,r))
print()
def getr(a,b): return rel.get((a,b),'EQ')
def ins(items):
    arr=list(items)
    for i in range(1,len(arr)):
        j=i
        while j>0 and getr(arr[j-1],arr[j])=='GT':
            arr[j-1],arr[j]=arr[j],arr[j-1]; j-=1
    return arr
outs=set()
for perm in itertools.permutations(props):
    r=order_of('a{'+';'.join('%s:1px'%p for p in perm)+'}')
    p=ins(list(perm))
    ok = ' '.join(r)==' '.join(p)
    print(' '.join(perm), '=>', ' '.join(r), '| pred', ' '.join(p), 'OK' if ok else 'MISMATCH')
""}

