                        self.pos = self.start;
                        self.number(true)
                    } else if c == '-' {
                        self.pos = self.start;
                        let v = self.ident();
                        Token::Ident(v)
                    } else if Self::is_ident_start(c) || Self::is_escape_start(c) {
                        self.pos = self.start;
                        let v = self.ident();
                        Token::Ident(v)
                    } else {
                        Token::Delim('-')
                    }
                } else {
                    Token::Delim('-')
                }
            }
            '+' => {
                if let Some(c) = self.at(self.pos) {
                    if c.is_ascii_digit()
                        || (c == '.' && matches!(self.peek(2), Some(c) if c.is_ascii_digit()))
