                        self.pos = self.start;
                        self.number(true)
                    } else {
                        Token::Delim('+')
                    }
                } else {
                    Token::Delim('+')
                }
            }
            '.' => {
                if let Some(c) = self.at(self.pos) {
                    if c.is_ascii_digit() {
                        self.pos = self.start;
                        self.number(false)
                    } else {
                        Token::Delim('.')
                    }
                } else {
                    Token::Delim('.')
                }
            }
            c if Self::is_ident_start(c) => {
                self.pos = self.start;
                let v = self.ident();
                if self.at(self.pos) == Some('(') {
                    self.pos += 1;
                    Token::Function(v)
                } else {
                    Token::Ident(v)
                }
            }
            c => Token::Delim(c),
        };
        (tok, self.start, self.pos)
    }

    /// Try to tokenize `url(` at position `s` (after the `(`).
    fn try_url(&mut self, s: usize) -> Option<Token<'a>> {
        let mut p = s;
