//! CSS tokenizer, following the CSS Syntax Level 3 specification.

#[derive(Debug, Clone, PartialEq)]
pub enum Token<'a> {
    /// A `<ident-token>`
    Ident(&'a str),
    /// A `<function-token>`: `<ident>(`
    Function(&'a str),
    /// `#` followed by an ident (id) or a name (unquoted)
    Hash {
        is_id: bool,
        value: &'a str,
    },
    /// A `<string-token>`
    Str(&'a str),
    /// A `<bad-string-token>`
    BadStr,
    /// `url(...)` with an unquoted URL
    UnquotedUrl(&'a str),
    /// A `<bad-url-token>`
    BadUrl,
    /// A `<number-token>` without a unit
    Number {
        has_sign: bool,
        value: f32,
        int_value: Option<i32>,
    },
    /// A `<percentage-token>`
    Percentage {
        has_sign: bool,
        value: f32,
        int_value: Option<i32>,
    },
    /// A `<dimension-token>`
    Dimension {
        has_sign: bool,
        value: f32,
        int_value: Option<i32>,
        unit: &'a str,
    },
    /// A `<whitespace-token>` (one or more consecutive whitespace)
    WhiteSpace,
    /// A `<comment-token>`
    Comment(&'a str),
    /// `:`
    Colon,
    /// `;`
    Semicolon,
    /// `,`
    Comma,
    /// Any other single character
    Delim(char),
    /// `[`
    OpenSquareBracket,
    /// `]`
    CloseSquareBracket,
    /// `(`
    OpenParenthesis,
    /// `)`
    CloseParenthesis,
    /// `{`
    OpenCurlyBracket,
    /// `}`
    CloseCurlyBracket,
    /// `~=`
    IncludeMatch,
    /// `|=`
    DashMatch,
    /// `^=`
    PrefixMatch,
    /// `$=`
    SuffixMatch,
    /// `*=`
    SubstringMatch,
    /// `||`
    Column,
    /// `::`
    CLOf,
    /// `<at-keyword>`
    AtKeyword(&'a str),
    /// EOF
    EOF,
}

impl<'a> Token<'a> {
    pub fn is_eof(&self) -> bool {
        matches!(self, Token::EOF)
    }

    /// Whitespace or comments are ignored by most rules.
    pub fn is_whitespace_or_comment(&self) -> bool {
        matches!(self, Token::WhiteSpace | Token::Comment(_))
    }
}

pub struct Tokenizer<'a> {
    src: &'a str,
    /// byte offset of the start of the current token
    start: usize,
    pos: usize,
    /// don't skip whitespace/comments (for raw serialization)
    pub include_whitespace: bool,
}

impl<'a> Tokenizer<'a> {
    pub fn new(src: &'a str) -> Tokenizer<'a> {
        Tokenizer {
            src,
            start: 0,
            pos: 0,
            include_whitespace: false,
        }
    }

    pub fn position(&self) -> usize {
        self.pos
    }

    pub fn start_position(&self) -> usize {
        self.start
    }

    /// Source slice of the token that was just returned.
    pub fn slice(&self, start: usize, end: usize) -> &'a str {
        &self.src[start..end]
    }

    fn at(&self, i: usize) -> Option<char> {
        self.src[i..].chars().next()
    }

    fn bump(&mut self) -> Option<char> {
        let c = self.at(self.pos)?;
        self.pos += c.len_utf8();
        Some(c)
    }

    fn peek(&self, n: usize) -> Option<char> {
        let mut p = self.pos;
        let mut c = None;
        for _ in 0..n {
            c = self.at(p)?;
            if c.is_none() {
                return None;
            }
            p += c.unwrap().len_utf8();
        }
        c
    }

    /// Consume a sequence of whitespace.
    fn whitespace(&mut self) {
        while let Some(c) = self.at(self.pos) {
            match c {
                ' ' | '\t' | '\n' | '\r' | '\x0c' => {
                    self.pos += c.len_utf8();
                }
                _ => break,
            }
        }
    }

    /// Consume a comment, assuming `/*` was just consumed.
    fn comment(&mut self) {
        // already consumed "/*"
        self.pos += 2;
        loop {
            match self.at(self.pos) {
                None => return,
                Some('*') => {
                    if let Some('/') = self.peek(2) {
                        self.pos += 4;
                        return;
                    }
                    self.pos += 1;
                }
                Some(c) => self.pos += c.len_utf8(),
            }
        }
    }

    fn is_ident_start(c: char) -> bool {
        c.is_alphabetic() || c == '_' || c == '-' || c >= '\u{80}'
    }

    fn is_ident_char(c: char) -> bool {
        c.is_alphanumeric() || c == '_' || c == '-' || c >= '\u{80}'
    }

    fn ident(&mut self) -> &'a str {
        let start = self.pos;
        while let Some(c) = self.at(self.pos) {
            if Self::is_ident_char(c) {
                self.pos += c.len_utf8();
            } else if c == '\\' {
                // escape: consume the escape sequence
                self.pos += 1;
                if let Some(c) = self.at(self.pos) {
                    if c == '\n' || c == '\r' || c == '\x0c' {
                        break;
                    }
                    self.pos += c.len_utf8();
                    // consume up to 6 hex digits
                    let mut n = 0;
                    while n < 6 {
                        match self.at(self.pos) {
                            Some(c) if c.is_ascii_hexdigit() => {
                                self.pos += 1;
                                n += 1;
                            }
                            _ => break,
                        }
                    }
                    if let Some(c) = self.at(self.pos) {
                        if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\x0c' {
                            self.pos += c.len_utf8();
                        }
                    }
                }
            } else {
                break;
            }
        }
        &self.src[start..self.pos]
    }

    fn is_escape_start(c: char) -> bool {
        c == '\\'
    }

    /// Compute the "would start identifier" check for a digit after `-`.
    fn digit_after_hyphen(&self) -> bool {
        // self.pos points right after '-'
        match self.at(self.pos) {
            Some(c) if c.is_ascii_digit() => true,
            Some('-') => matches!(self.at(self.pos + 1), Some(c) if c.is_ascii_hexdigit()),
            Some('\\') => {
                let mut p = self.pos + 1;
                if let Some(c) = self.at(p) {
                    p += c.len_utf8();
                    let mut n = 0;
                    let mut has = false;
                    while n < 6 {
                        match self.at(p) {
                            Some(c) if c.is_ascii_hexdigit() => {
                                p += 1;
                                n += 1;
                                has = true;
                            }
                            _ => break,
                        }
                    }
                    has
                } else {
                    false
                }
            }
            _ => false,
        }
    }

    fn number(&mut self, has_sign: bool) -> Token<'a> {
        let start = self.pos;
        let mut is_int = true;
        // integer digits
        while let Some(c) = self.at(self.pos) {
            if c.is_ascii_digit() {
                self.pos += 1;
            } else {
                break;
            }
        }
        if let Some('.') = self.at(self.pos) {
            if let Some(c) = self.peek(2) {
                if c.is_ascii_digit() {
                    is_int = false;
                    self.pos += 1;
                    while let Some(c) = self.at(self.pos) {
                        if c.is_ascii_digit() {
                            self.pos += 1;
                        } else {
                            break;
                        }
                    }
                }
            }
        }
        if let Some(c) = self.at(self.pos) {
            if c == 'e' || c == 'E' {
                let mut p = self.pos + 1;
                let mut has_exp_digits = false;
                if let Some(s) = self.at(p) {
                    if s == '+' || s == '-' {
                        p += 1;
                    }
                }
                while let Some(c) = self.at(p) {
                    if c.is_ascii_digit() {
                        p += 1;
                        has_exp_digits = true;
                    } else {
                        break;
                    }
                }
                if has_exp_digits {
                    is_int = false;
                    // must be followed by an ident char to be part of the number
                    match self.at(p) {
                        Some(c) if Self::is_ident_char(c) => {
                            // it's a dimension with unit starting with e
                        }
                        _ => {
                            self.pos = p;
                        }
                    }
                }
            }
        }
        let num_str = &self.src[start..self.pos];
        let value = parse_number(num_str);
        let int_value = if is_int {
            let s = num_str.trim_start_matches('+');
            match s.parse::<i32>() {
                Ok(i) => Some(i),
                Err(_) => None,
            }
        } else {
            None
        };
        // unit?
        match self.at(self.pos) {
            Some('%') => {
                self.pos += 1;
                Token::Percentage {
                    has_sign,
                    value,
                    int_value,
                }
            }
            Some(c) if Self::is_ident_start(c) || Self::is_escape_start(c) => {
                let unit = self.ident();
                Token::Dimension {
                    has_sign,
                    value,
                    int_value,
                    unit,
                }
            }
            _ => Token::Number {
                has_sign,
                value,
                int_value,
            },
        }
    }

    /// Return the next token, skipping whitespace and comments unless
    /// `include_whitespace` is set.
    pub fn next(&mut self) -> (Token<'a>, usize, usize) {
        loop {
            self.start = self.pos;
            if self.pos >= self.src.len() {
                return (Token::EOF, self.pos, self.pos);
            }
            let (tok, s, e) = self.next_including_whitespace();
            if self.include_whitespace {
                return (tok, s, e);
            }
            if matches!(tok, Token::WhiteSpace | Token::Comment(_)) {
                continue;
            }
            return (tok, s, e);
        }
    }

    pub fn next_including_whitespace(&mut self) -> (Token<'a>, usize, usize) {
        self.start = self.pos;
        let c = match self.bump() {
            None => return (Token::EOF, self.pos, self.pos),
            Some(c) => c,
        };
        let tok = match c {
            ' ' | '\t' | '\n' | '\r' | '\x0c' => {
                self.whitespace();
                Token::WhiteSpace
            }
            '/' => {
                if let Some('*') = self.at(self.pos) {
                    self.comment();
                    let text = &self.src[self.start + 2..self.pos - 2];
                    Token::Comment(text)
                } else {
                    Token::Delim('/')
                }
            }
            ':' => {
                if let Some(':') = self.at(self.pos) {
                    self.pos += 1;
                    Token::CLOf
                } else {
                    Token::Colon
                }
            }
            ';' => Token::Semicolon,
            ',' => Token::Comma,
            '[' => Token::OpenSquareBracket,
            ']' => Token::CloseSquareBracket,
            '(' => Token::OpenParenthesis,
            ')' => Token::CloseParenthesis,
            '{' => Token::OpenCurlyBracket,
            '}' => Token::CloseCurlyBracket,
            '~' => {
                if let Some('=') = self.at(self.pos) {
                    self.pos += 1;
                    Token::IncludeMatch
                } else {
                    Token::Delim('~')
                }
            }
            '|' => {
                if let Some('=') = self.at(self.pos) {
                    self.pos += 1;
                    Token::DashMatch
                } else if let Some('|') = self.at(self.pos) {
                    self.pos += 1;
                    Token::Column
                } else {
                    Token::Delim('|')
                }
            }
            '^' => {
                if let Some('=') = self.at(self.pos) {
                    self.pos += 1;
                    Token::PrefixMatch
                } else {
                    Token::Delim('^')
                }
            }
            '$' => {
                if let Some('=') = self.at(self.pos) {
                    self.pos += 1;
                    Token::SuffixMatch
                } else {
                    Token::Delim('$')
                }
            }
            '*' => {
                if let Some('=') = self.at(self.pos) {
                    self.pos += 1;
                    Token::SubstringMatch
                } else {
                    Token::Delim('*')
                }
            }
            '@' => {
                let start = self.pos;
                let name = self.ident();
                if name.is_empty() {
                    Token::Delim('@')
                } else {
                    Token::AtKeyword(name)
                }
            }
            '"' | '\'' => self.string(c),
            '#' => {
                let start = self.pos;
                if let Some(c) = self.at(self.pos) {
                    if Self::is_ident_char(c) || Self::is_escape_start(c) {
                        let v = self.ident();
                        // is_id: does not start with a digit, and no digit follows a hyphen
                        let first = v.chars().next().unwrap();
                        let is_id = !(first.is_ascii_digit())
                            && !(first == '-'
                                && v.chars()
                                    .nth(1)
                                    .map(|c| c.is_ascii_digit())
                                    .unwrap_or(false));
                        Token::Hash {
                            is_id,
                            value: &self.src[start..self.pos],
                        }
                    } else {
                        self.pos = start;
                        Token::Delim('#')
                    }
                } else {
                    Token::Delim('#')
                }
            }
            '\\' => {
                // escape at start of ident
                self.pos = self.start;
                let v = self.ident();
                Token::Ident(v)
            }
            'u' | 'U' => {
                if self.at(self.pos) == Some('+') {
                    // unicode-range style, but per spec it's a number + ident
                    // handled by caller; here treat as ident continuation
                    self.pos = self.start;
                    let v = self.ident();
                    Token::Ident(v)
                } else if let Some('(') = self.at(self.pos) {
                    // possible url()
                    let s = self.pos + 1;
                    if let Some(t) = self.try_url(s) {
                        t
                    } else {
                        self.pos = self.start;
                        let v = self.ident();
                        self.pos += 1;
                        Token::Function(v)
                    }
                } else {
                    self.pos = self.start;
                    let v = self.ident();
                    Token::Ident(v)
                }
            }
            c if c.is_ascii_digit() => {
                self.pos = self.start;
                self.number(false)
            }
            '-' => {
                // "-" alone, or "-<number>", "--<ident>", "-<ident>"
                if self.at(self.pos).is_none() {
                    Token::Delim('-')
                } else if let Some(c) = self.at(self.pos) {
                    if c.is_ascii_digit()
                        || (c == '.' && matches!(self.peek(2), Some(c) if c.is_ascii_digit()))
                    {
                        self.pos = self.start;
                        self.number(true)
                    } else if c == '-' {
                        self.pos = self.start;
                        let v = self.ident();
                        Token::Ident(v)
                    } else if Self::is_ident_start(c) || Self::is_escape_start(c) {
                        self.pos = self.start;
                        let v = self.ident();
                        Token::Ident(v)
                    } else {
                        Token::Delim('-')
                    }
                } else {
                    Token::Delim('-')
                }
            }
            '+' => {
                if let Some(c) = self.at(self.pos) {
                    if c.is_ascii_digit()
                        || (c == '.' && matches!(self.peek(2), Some(c) if c.is_ascii_digit()))
                    {
                        self.pos = self.start;
                        self.number(true)
                    } else {
                        Token::Delim('+')
                    }
                } else {
                    Token::Delim('+')
                }
            }
            '.' => {
                if let Some(c) = self.at(self.pos) {
                    if c.is_ascii_digit() {
                        self.pos = self.start;
                        self.number(false)
                    } else {
                        Token::Delim('.')
                    }
                } else {
                    Token::Delim('.')
                }
            }
            c if Self::is_ident_start(c) => {
                self.pos = self.start;
                let v = self.ident();
                if self.at(self.pos) == Some('(') {
                    self.pos += 1;
                    Token::Function(v)
                } else {
                    Token::Ident(v)
                }
            }
            c => Token::Delim(c),
        };
        (tok, self.start, self.pos)
    }

    /// Try to tokenize `url(` at position `s` (after the `(`).
    fn try_url(&mut self, s: usize) -> Option<Token<'a>> {
        let mut p = s;
        // skip whitespace
        let mut saw_ws = false;
        while let Some(c) = self.at(p) {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\x0c' {
                p += c.len_utf8();
                saw_ws = true;
            } else {
                break;
            }
        }
        if saw_ws {
            // not an unquoted url
            return None;
        }
        let start = p;
        let mut end = None;
        while let Some(c) = self.at(p) {
            match c {
                ')' => {
                    end = Some(p);
                    break;
                }
                ' ' | '\t' | '\n' | '\r' | '\x0c' => {
                    // whitespace inside url: must be followed by ')' to be valid
                    let mut q = p;
                    while let Some(c2) = self.at(q) {
                        if c2 == ' ' || c2 == '\t' || c2 == '\n' || c2 == '\r' || c2 == '\x0c' {
                            q += c2.len_utf8();
                        } else {
                            break;
                        }
                    }
                    if self.at(q) == Some(')') {
                        end = Some(p);
                        break;
                    }
                    // bad url: consume until matching ) accounting for escapes
                    let mut q = p;
                    while let Some(c2) = self.at(q) {
                        if c2 == '\\' {
                            q += 1;
                            if let Some(c3) = self.at(q) {
                                q += c3.len_utf8();
                            }
                        } else if c2 == ')' {
                            break;
                        } else {
                            q += c2.len_utf8();
                        }
                    }
                    self.pos = q;
                    if self.at(q) == Some(')') {
                        self.pos += 1;
                    }
                    return Some(Token::BadUrl);
                }
                '"' | '\'' | '(' => {
                    // bad url
                    let mut q = p;
                    while let Some(c2) = self.at(q) {
                        if c2 == '\\' {
                            q += 1;
                            if let Some(c3) = self.at(q) {
                                q += c3.len_utf8();
                            }
                        } else if c2 == ')' {
                            break;
                        } else {
                            q += c2.len_utf8();
                        }
                    }
                    self.pos = q;
                    if self.at(q) == Some(')') {
                        self.pos += 1;
                    }
                    return Some(Token::BadUrl);
                }
                '\\' => {
                    p += 1;
                    if let Some(c2) = self.at(p) {
                        if c2 == '\n' || c2 == '\r' || c2 == '\x0c' {
                            return None;
                        }
                        p += c2.len_utf8();
                    }
                }
                c if c.is_nonprinting() => {
                    return None;
                }
                _ => p += c.len_utf8(),
            }
        }
        let e = end?;
        self.pos = e + 1;
        Some(Token::UnquotedUrl(&self.src[start..e]))
    }

    fn string(&mut self, quote: char) -> Token<'a> {
        let mut p = self.pos;
        loop {
            match self.at(p) {
                None => {
