impl<'a> Tokenizer<'a> {
    pub fn new(src: &'a str) -> Tokenizer<'a> {
        Tokenizer {
            src,
            start: 0,
            pos: 0,
            include_whitespace: false,
        }
    }

    pub fn position(&self) -> usize {
        self.pos
    }

    pub fn start_position(&self) -> usize {
        self.start
    }

