                    p += c.len_utf8();
                    let mut n = 0;
                    let mut has = false;
                    while n < 6 {
                        match self.at(p) {
                            Some(c) if c.is_ascii_hexdigit() => {
                                p += 1;
                                n += 1;
                                has = true;
                            }
                            _ => break,
                        }
                    }
                    has
                } else {
                    false
                }
            }
            _ => false,
