                if let Some('=') = self.at(self.pos) {
                    self.pos += 1;
                    Token::DashMatch
                } else if let Some('|') = self.at(self.pos) {
                    self.pos += 1;
                    Token::Column
                } else {
                    Token::Delim('|')
                }
