    /// Try to tokenize `url(` at position `s` (after the `(`).
    fn try_url(&mut self, s: usize) -> Option<Token<'a>> {
        let mut p = s;
        // skip whitespace
        let mut saw_ws = false;
        while let Some(c) = self.at(p) {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\x0c' {
                p += c.len_utf8();
                saw_ws = true;
            } else {
                break;
            }
        }
        if saw_ws {
            // not an unquoted url
            return None;
        }
        let start = p;
        let mut end = None;
        while let Some(c) = self.at(p) {
            match c {
                ')' => {
                    end = Some(p);
                    break;
                }
                ' ' | '\t' | '\n' | '\r' | '\x0c' => {
                    // whitespace inside url: must be followed by ')' to be valid
                    let mut q = p;
                    while let Some(c2) = self.at(q) {
                        if c2 == ' ' || c2 == '\t' || c2 == '\n' || c2 == '\r' || c2 == '\x0c' {
                            q += c2.len_utf8();
                        } else {
                            break;
                        }
                    }
                    if self.at(q) == Some(')') {
                        end = Some(p);
                        break;
                    }
                    // bad url: consume until matching ) accounting for escapes
                    let mut q = p;
                    while let Some(c2) = self.at(q) {
                        if c2 == '\\' {
                            q += 1;
                            if let Some(c3) = self.at(q) {
                                q += c3.len_utf8();
                            }
                        } else if c2 == ')' {
                            break;
                        } else {
                            q += c2.len_utf8();
                        }
                    }
                    self.pos = q;
                    if self.at(q) == Some(')') {
                        self.pos += 1;
                    }
                    return Some(Token::BadUrl);
                }
                '"' | '\'' | '(' => {
                    // bad url
                    let mut q = p;
                    while let Some(c2) = self.at(q) {
                        if c2 == '\\' {
                            q += 1;
                            if let Some(c3) = self.at(q) {
                                q += c3.len_utf8();
                            }
                        } else if c2 == ')' {
                            break;
                        } else {
                            q += c2.len_utf8();
                        }
                    }
                    self.pos = q;
                    if self.at(q) == Some(')') {
                        self.pos += 1;
                    }
                    return Some(Token::BadUrl);
                }
                '\\' => {
                    p += 1;
                    if let Some(c2) = self.at(p) {
                        if c2 == '\n' || c2 == '\r' || c2 == '\x0c' {
                            return None;
                        }
                        p += c2.len_utf8();
                    }
                }
                c if c.is_nonprinting() => {
                    return None;
                }
                _ => p += c.len_utf8(),
            }
        }
        let e = end?;
        self.pos = e + 1;
        Some(Token::UnquotedUrl(&self.src[start..e]))
    }

    fn string(&mut self, quote: char) -> Token<'a> {
        let mut p = self.pos;
        loop {
            match self.at(p) {
                None => {
                    self.pos = p;
                    return Token::BadStr;
                }
                Some(c) if c == quote => {
                    p += 1;
                    let v = unescape_string(&self.src[self.pos..p - 1]);
                    self.pos = p;
                    return Token::Str(v);
                }
                Some('\\') => {
                    p += 1;
                    match self.at(p) {
                        None => {
                            self.pos = p;
                            return Token::BadStr;
                        }
                        Some(c) if c == '\n' || c == '\r' || c == '\x0c' => {
                            p += c.len_utf8();
                        }
                        Some(c) => p += c.len_utf8(),
                    }
                }
                Some(c) if c == '\n' || c == '\r' || c == '\x0c' => {
                    self.pos = p;
                    return Token::BadStr;
                }
                Some(c) => p += c.len_utf8(),
            }
        }
    }
}

trait NonPrinting {
    fn is_nonprinting(&self) -> bool;
}
impl NonPrinting for char {
    fn is_nonprinting(&self) -> bool {
        matches!(*self, '\0'..='\x08' | '\x0b' | '\x0e'..='\x1f' | '\x7f')
    }
}

/// Parse a CSS number (with optional exponent) into an f32, saturating at f32::MAX.
pub fn parse_number(s: &str) -> f32 {
    let v: f32 = s.parse().unwrap_or(0.0);
    if v.is_infinite() {
        if v > 0.0 {
            f32::MAX
        } else {
            -f32::MAX
        }
    } else {
        v
    }
}

pub fn unescape_string(s: &str) -> &str {
    // Only handle the common case of no escapes; escaped text is handled by the
    // string serializer which re-escapes what it needs to.
    s
}
