//! Parse errors, matching lightningcss's error kinds.

#[derive(Debug, Clone, PartialEq)]
pub enum ErrorKind {
    EndOfInput,
    UnexpectedImportRule,
    AtRuleBodyInvalid,
    UnexpectedToken(String),
    UnexpectedIdent(String),
    InvalidDeclaration,
    SelectorError(String),
    UnknownAtRule(String),
    CustomMediaNotEnabled,
    KeyframesInvalid,
    SpecifierError,
    ResolverError(String),
    InvalidValue,
    UnexpectedDeclaration,
    NotABlock,
}

#[derive(Debug, Clone)]
pub struct Error {
    pub kind: ErrorKind,
    pub filename: String,
    /// 0-based line
    pub line: usize,
    /// 1-based column
    pub column: usize,
    pub has_loc: bool,
}

impl Error {
    pub fn new(kind: ErrorKind, filename: &str, source: &str, pos: usize) -> Error {
        let (line, column) = line_col(source, pos);
        Error {
            kind,
            filename: filename.to_string(),
            line,
            column,
            has_loc: true,
        }
    }
    pub fn no_loc(kind: ErrorKind) -> Error {
        Error {
            kind,
            filename: String::new(),
            line: 0,
            column: 0,
            has_loc: false,
        }
    }
}

/// Compute a 0-based line and 1-based column for a byte offset.
pub fn line_col(source: &str, pos: usize) -> (usize, usize) {
    let pos = pos.min(source.len());
    let mut line = 0;
    let mut col = 0;
    let mut i = 0;
    for c in source[..pos].chars() {
        if c == '\n' {
            line += 1;
            col = 0;
        } else {
            col += 1;
        }
        i += c.len_utf8();
    }
    let _ = i;
    (line, col)
}
RSEOF
echo ok"}

