/// Parse a hex color like #fff, #ffffff, #ff00ff00.
pub fn parse_hex(s: &str) -> Option<(u8, u8, u8, f32)> {
    let h = s.strip_prefix('#')?;
    let len = h.len();
    let mut digits = Vec::new();
    for c in h.chars() {
        let v = match c {
            '0'..='9' => c as u8 - b'0',
            'a'..='f' => c as u8 - b'a' + 10,
            'A'..='F' => c as u8 - b'A' + 10,
            _ => return None,
        };
        digits.push(v);
    }
    match len {
        3 => Some((
            digits[0] * 17,
            digits[1] * 17,
            digits[2] * 17,
            1.0,
        )),
        4 => Some((
            digits[0] * 17,
            digits[1] * 17,
            digits[2] * 17,
            digits[3] as f32 * 17.0 / 255.0,
        )),
        6 => Some((
            digits[0] * 16 + digits[1],
            digits[2] * 16 + digits[3],
            digits[4] * 16 + digits[5],
            1.0,
        )),
        8 => Some((
            digits[0] * 16 + digits[1],
            digits[2] * 16 + digits[3],
            digits[4] * 16 + digits[5],
            (digits[6] * 16 + digits[7]) as f32 / 255.0,
        )),
        _ => None,
    }
}

pub fn clamp_u8(v: f32) -> u8 {
    if v.is_nan() {
        0
    } else if v <= 0.0 {
        0
    } else if v >= 255.0 {
        255
    } else {
        (v + 0.5).floor() as u8
    }
}

pub fn clamp01(v: f32) -> f32 {
    if v.is_nan() {
        0.0
    } else if v <= 0.0 {
        0.0
    } else if v >= 1.0 {
        1.0
    } else {
        v
    }
}

pub fn hsl_to_rgb(h: f32, s: f32, l: f32) -> (u8, u8, u8) {
    let h = if h.is_finite() { h.rem_euclid(360.0) } else { 0.0 };
    let s = clamp01(s);
    let l = clamp01(l);
    let c = (1.0 - (2.0 * l - 1.0).abs()) * s;
    let hp = h / 60.0;
    let x = c * (1.0 - (hp.rem_euclid(2.0) - 1.0).abs());
    let (r1, g1, b1) = match hp {
        v if v < 1.0 => (c, x, 0.0),
        v if v < 2.0 => (x, c, 0.0),
        v if v < 3.0 => (0.0, c, x),
        v if v < 4.0 => (0.0, x, c),
        v if v < 5.0 => (x, 0.0, c),
        _ => (c, 0.0, x),
    };
    let m = l - c / 2.0;
    (
        clamp_u8((r1 + m) * 255.0),
        clamp_u8((g1 + m) * 255.0),
        clamp_u8((b1 + m) * 255.0),
    )
}

pub fn rgb_to_hsl(r: u8, g: u8, b: u8) -> (f32, f32, f32) {
    let r = r as f32 / 255.0;
    let g = g as f32 / 255.0;
    let b = b as f32 / 255.0;
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let l = (max + min) / 2.0;
    if max == min {
        return (0.0, 0.0, l);
    }
    let d = max - min;
    let s = if l > 0.5 { d / (2.0 - max - min) } else { d / (max + min) };
    let h = if max == r {
        ((g - b) / d) % 6.0
    } else if max == g {
        (b - r) / d + 2.0
    } else {
        (r - g) / d + 4.0
    };
    let h = h * 60.0;
    (h.rem_euclid(360.0), s, l)
}

pub fn rgb_to_hwb(r: u8, g: u8, b: u8) -> (f32, f32, f32) {
    let max = r.max(g).max(b) as f32 / 255.0;
    let min = r.min(g).min(b) as f32 / 255.0;
    let (h, _, _) = rgb_to_hsl(r, g, b);
    (h, min, 1.0 - max)
}

pub fn hwb_to_rgb(h: f32, w: f32, bl: f32) -> (u8, u8, u8) {
    if w + bl >= 1.0 {
        let g = w / (w + bl);
        return (clamp_u8(g * 255.0), clamp_u8(g * 255.0), clamp_u8(g * 255.0));
    }
    let (r0, g0, b0) = hsl_to_rgb(h, 1.0, 0.5);
    let w = clamp01(w);
    let bl = clamp01(bl);
    let f = |v: u8| (v as f32 / 255.0) * (1.0 - w - bl) + w;
    (
        clamp_u8(f(r0) * 255.0),
        clamp_u8(f(g0) * 255.0),
        clamp_u8(f(b0) * 255.0),
    )
}

/// Write a hex color, choosing the shortest of the possible representations.
pub fn serialize_color(c: &Color, minify: bool, out: &mut String) {
    match c {
        Color::Raw(s) => out.push_str(s),
        Color::CurrentColor => out.push_str("currentcolor"),
        Color::Transparent => out.push_str("transparent"),
        Color::Rgba(r, g, b, a) => {
            if !minify {
                out.push_str("rgba(");
                out.push_str(&r.to_string());
                out.push_str(", ");
                out.push_str(&g.to_string());
                out.push_str(", ");
                out.push_str(&b.to_string());
                out.push_str(", ");
                serialize_number(*a, None, out);
                out.push(')');
                return;
            }
            let a = clamp01(*a);
            if a >= 1.0 {
                // choose between hex, short hex and named colors
                let rgb = (*r, *g, *b);
                if let Some(name) = shortest_named(rgb) {
                    out.push_str(name);
                    return;
                }
                let all_eq = r == g && g == b;
                if all_eq {
                    let hex = format!("#{:02x}{:02x}", r, r);
                    out.push_str(&hex);
                    return;
                }
                let hex = format!("#{:02x}{:02x}{:02x}", r, g, b);
                out.push_str(&hex);
            } else {
                let alpha = (a * 255.0).round() as u8;
                if alpha % 17 == 0 && alpha != 0 {
                    // can be written as a single hex digit
                    let d = alpha / 17;
                    let all_eq = r == g && g == b;
                    if all_eq {
                        let hex = format!("#{:02x}{:02x}{:x}", r, r, d);
                        out.push_str(&hex);
                    } else {
                        let hex = format!("#{:02x}{:02x}{:02x}{:x}", r, g, b, d);
                        out.push_str(&hex);
                    }
                    return;
                }
                let hex = format!("#{:02x}{:02x}{:02x}{:02x}", r, g, b, alpha);
                out.push_str(&hex);
            }
        }
        Color::Hsla(h, s, l, a) => {
            if !minify {
                out.push_str("hsl(");
                serialize_number(*h, None, out);
                out.push_str(", ");
                serialize_number(*s, None, out);
                out.push_str(", ");
                serialize_number(*l, None, out);
                out.push(')');
                return;
            }
            let (r, g, b) = hsl_to_rgb(*h, *s / 100.0, *l / 100.0);
            let mut tmp = Color::Rgba(r, g, b, *a);
            serialize_color(&tmp, minify, out);
        }
        _ => out.push_str("rgba(0, 0, 0, 1)"),
    }
}

fn shortest_named(rgb: (u8, u8, u8)) -> Option<&'static str> {
    let mut best: Option<&'static str> = None;
    for name in NAMES {
        if let Some(c) = named_color(name) {
            if c == rgb {
                if best.is_none() || name.len() < best.unwrap().len() {
                    best = Some(name);
                }
            }
        }
    }
    best
}

