/// Serialize a number the way lightningcss does: 6 significant digits,
/// exponential notation outside [1e-6, 1e21).
pub fn serialize_number(value: f32, int_value: Option<i32>, out: &mut String) {
    if let Some(i) = int_value {
        out.push_str(&i.to_string());
        return;
    }
    if value == 0.0 {
        if value.is_sign_negative() {
            // negative zero is serialized as 0
        }
        out.push('0');
        return;
    }
    let neg = value < 0.0;
    let av = value.abs();
    let sci = format!("{:.5e}", av);
    // sci is like "1.23457e6" or "3.40282e38"
    let (mant, exp) = match sci.split_once('e') {
        Some((m, e)) => (m.to_string(), e.parse::<i32>().unwrap_or(0)),
        None => (sci.clone(), 0),
    };
    let mant = strip_trailing_zeros(&mant);
    if exp < -6 || exp >= 21 {
        if neg {
            out.push('-');
        }
        out.push_str(&mant);
        out.push('e');
        out.push_str(&exp.to_string());
        return;
    }
    // decimal notation
    let s = if exp >= 0 {
        decimal_from_sci(&mant, exp as usize)
    } else {
        let n = (-exp) as usize;
        let mut r = String::from("0.");
        for _ in 1..n {
            r.push('0');
        }
        let digits: String = mant.chars().filter(|c| *c != '.').collect();
        r.push_str(&digits);
        r
    };
    let s = strip_leading_zero(&s);
    if neg {
        out.push('-');
    }
    out.push_str(&s);
}

fn strip_trailing_zeros(s: &str) -> String {
    if !s.contains('.') {
        return s.to_string();
    }
    let s = s.trim_end_matches('0');
    let s = s.trim_end_matches('.');
    s.to_string()
}

fn strip_leading_zero(s: &str) -> String {
    if let Some(rest) = s.strip_prefix("0.") {
        format!(".{}", rest)
    } else {
        s.to_string()
    }
}

/// Expand a mantissa (which may contain a '.') by `exp` positions to plain decimal.
fn decimal_from_sci(mant: &str, exp: usize) -> String {
    let int_len = mant.find('.').unwrap_or(mant.len());
    let digits: String = mant.chars().filter(|c| *c != '.').collect();
    let digits = digits.trim_end_matches('0');
    let digits = if digits.is_empty() { "0" } else { digits };
    if int_len > exp {
        // decimal point inside the digits
        let (a, b) = digits.split_at(int_len);
        format!("{}.{}", a, b)
    } else {
        let mut r = digits.to_string();
        for _ in 0..(exp + 1 - digits.len().max(int_len)) {
            r.push('0');
        }
        r
    }
}

