    pub filename: String,
    pub custom_media: bool,
    pub css_modules: bool,
    pub error_recovery: bool,
    pub errors: Vec<Error>,
}

impl<'a> Parser<'a> {
    pub fn new(src: &'a str, filename: &str, options: ParseOptions) -> Parser<'a> {
        let mut tok = Tokenizer::new(src);
        let (cur, s, e) = tok.next();
        Parser {
            src,
            tok,
            cur,
            cur_start: s,
            cur_end: e,
            filename: filename.to_string(),
            custom_media: options.custom_media,
            css_modules: options.css_modules,
            error_recovery: options.error_recovery,
            errors: Vec::new(),
        }
    }

    fn bump(&mut self) {
        let (t, s, e) = self.tok.next();
        self.cur = t;
        self.cur_start = s;
        self.cur_end = e;
    }

    /// Skip whitespace and comments.
    fn skip_ws(&mut self) {
        while self.cur.is_whitespace_or_comment() {
            self.bump();
        }
    }

    fn peek(&mut self) -> Token<'a> {
        // Peek by saving/restoring the tokenizer state.
        let saved_pos = self.tok.position();
        let saved_include = self.tok.include_whitespace;
        let saved_cur = self.cur.clone();
        let saved_s = self.cur_start;
        let saved_e = self.cur_end;
        self.bump();
        let t = self.cur.clone();
        self.tok.include_whitespace = saved_include;
        // restore
        self.tok = Tokenizer::new(self.src);
        // fast-forward
        let mut p = saved_pos;
        // we cannot set position directly; re-scan is O(n) but acceptable for peeking
        // Instead, store position in Tokenizer.
        self.tok.set_position(p);
        self.cur = saved_cur;
        self.cur_start = saved_s;
        self.cur_end = saved_e;
        t
    }

    fn error(&mut self, kind: ErrorKind) {
        let e = Error::new(kind, &self.filename, self.src, self.cur_start);
        if self.error_recovery {
            self.errors.push(e);
        }
    }

    fn parse_error(&mut self, kind: ErrorKind) -> Error {
        Error::new(kind, &self.filename, self.src, self.cur_start)
    }

    /// Parse an entire stylesheet.
    pub fn parse_stylesheet(&mut self) -> Result<Stylesheet, Error> {
        let mut rules = Vec::new();
        loop {
            self.skip_ws();
            if self.cur.is_eof() {
                break;
            }
            match self.parse_rule() {
                Ok(Some(r)) => rules.push(r),
                Ok(None) => {}
                Err(e) => {
                    if self.error_recovery {
                        self.errors.push(e);
                        // skip to the next `}` or `;` at top level
                        self.skip_to_rule_end();
                        continue;
                    }
                    return Err(e);
                }
            }
        }
        Ok(Stylesheet { rules })
    }

    fn skip_to_rule_end(&mut self) {
        let mut depth = 0;
        loop {
            match self.cur.clone() {
                Token::EOF => break,
                Token::OpenCurlyBracket => {
                    depth += 1;
                    self.bump();
                }
                Token::CloseCurlyBracket => {
                    depth -= 1;
                    self.bump();
                    if depth <= 0 {
                        break;
                    }
                }
                Token::Semicolon if depth == 0 => {
                    self.bump();
                    break;
                }
                _ => self.bump(),
            }
        }
    }

    fn parse_rule(&mut self) -> Result<Option<Rule>, Error> {
        match self.cur.clone() {
            Token::AtKeyword(name) => {
                let name = name.to_string();
                self.bump();
                self.parse_at_rule(&name)
            }
            Token::EOF => Ok(None),
            _ => self.parse_qualified_rule(),
        }
    }

    fn parse_qualified_rule(&mut self) -> Result<Option<Rule>, Error> {
        // Parse the selector prelude up to `{`.
        let mut raw = String::new();
        let mut depth = 0;
        loop {
            match self.cur.clone() {
                Token::EOF => {
                    return Err(Error::new(
                        ErrorKind::EndOfInput,
                        &self.filename,
                        self.src,
                        self.cur_start,
                    ))
                }
                Token::OpenCurlyBracket if depth == 0 => break,
                Token::OpenCurlyBracket | Token::OpenParenthesis | Token::OpenSquareBracket => {
                    depth += 1;
                    raw.push_str(&self.token_text());
                    self.bump();
                }
                Token::CloseCurlyBracket | Token::CloseParenthesis | Token::CloseSquareBracket => {
                    if depth == 0 {
                        return Err(Error::new(
                            ErrorKind::UnexpectedToken(format!("{:?}", self.cur.clone())),
                            &self.filename,
                            self.src,
                            self.cur_start,
                        ));
                    }
                    depth -= 1;
                    raw.push_str(&self.token_text());
                    self.bump();
                }
                _ => {
                    raw.push_str(&self.token_text());
                    self.bump();
                }
            }
        }
        let selector_text = raw.trim().to_string();
        let selectors = split_selectors(&selector_text);
        self.bump(); // consume `{`
        let block = self.parse_declaration_block(true)?;
        Ok(Some(Rule::Style {
            selectors,
            block,
        }))
    }

    fn token_text(&self) -> String {
        let s = &self.src[self.cur_start..self.cur_end];
        s.to_string()
    }

    /// Parse the body of a block, terminated by `}` or EOF.
    fn parse_declaration_block(&mut self, is_style: bool) -> Result<DeclarationBlock, Error> {
        let mut block = DeclarationBlock::default();
        loop {
            self.skip_ws();
            match self.cur.clone() {
                Token::EOF | Token::CloseCurlyBracket => break,
                Token::Semicolon => {
                    self.bump();
                }
                Token::AtKeyword(name) => {
                    let name = name.to_string();
                    // Nested at-rules are handled by parse_nested_rule.
                    let r = self.parse_nested_at_rule(&name)?;
                    match r {
                        NestedItem::AtRule(rule) => {
                            // Declarations and nested rules cannot be mixed in a
                            // DeclarationBlock in this simplified model, so we
                            // close the block here and let the caller handle it.
                            return Err(Error::new(
                                ErrorKind::AtRuleBodyInvalid,
                                &self.filename,
                                self.src,
                                self.cur_start,
                            ));
                        }
                        NestedItem::Declaration(d) => block.declarations.push(d),
                    }
                    let _ = rule;
                }
                _ => {
                    let d = self.parse_declaration()?;
                    if let Some(d) = d {
                        block.declarations.push(d);
                    }
                }
            }
        }
        Ok(block)
    }

    /// Parse a single declaration (`ident: value[!important]`).
    fn parse_declaration(&mut self) -> Result<Option<Declaration>, Error> {
        // custom property?
        if let Token::Ident(name) = self.cur.clone() {
            if name.starts_with("--") {
                self.bump();
                self.skip_ws();
                if self.cur != Token::Colon {
                    return Err(self.parse_error(ErrorKind::EndOfInput));
                }
                self.bump();
                let value = self.parse_raw_value(true);
                let important = self.parse_important();
                self.consume_semicolon();
                return Ok(Some(Declaration {
                    property: name.to_string(),
                    value: Value::Raw(value),
                    important,
                    prefix: None,
                }));
            }
        }
        let (property, prefix) = match self.cur.clone() {
            Token::Ident(name) => {
                self.bump();
                (name.to_string(), None)
            }
            Token::Delim('-') => {
                // vendor prefix
                self.bump();
                let prefix = match self.cur.clone() {
                    Token::Ident(p) if matches!(p, "webkit" | "moz" | "ms" | "o") => {
                        self.bump();
                        p.to_string()
                    }
                    _ => return Err(self.parse_error(ErrorKind::InvalidDeclaration)),
                };
                let p: &'static str = match prefix.as_str() {
                    "webkit" => "webkit",
                    "moz" => "moz",
                    "ms" => "ms",
                    "o" => "o",
                    _ => "webkit",
                };
                match self.cur.clone() {
                    Token::Ident(name) => {
                        self.bump();
                        (name.to_string(), Some(p))
                    }
                    _ => return Err(self.parse_error(ErrorKind::InvalidDeclaration)),
                }
            }
            _ => {
                return Err(self.parse_error(ErrorKind::InvalidDeclaration));
            }
        };
        self.skip_ws();
        if self.cur != Token::Colon {
            return Err(self.parse_error(ErrorKind::EndOfInput));
        }
        self.bump();
        let value = self.parse_value()?;
        let important = self.parse_important();
        self.consume_semicolon();
        Ok(Some(Declaration {
            property,
            value,
            important,
            prefix,
        }))
    }

    fn parse_important(&mut self) -> bool {
        // `!important` with optional whitespace
        let save_pos = self.tok.position();
        let save_cur = self.cur.clone();
        let save_s = self.cur_start;
        let save_e = self.cur_end;
        self.skip_ws();
        if self.cur == Token::Delim('!') {
            self.bump();
            self.skip_ws();
            if let Token::Ident(name) = self.cur.clone() {
                if name.eq_ignore_ascii_case("important") {
                    self.bump();
                    return true;
                }
            }
        }
        // restore
        self.tok.set_position(save_pos);
        let (t, s, e) = self.tok.next();
        self.cur = t;
        self.cur_start = s;
        self.cur_end = e;
        let _ = (save_cur, save_s, save_e);
        false
    }

    fn consume_semicolon(&mut self) {
        self.skip_ws();
        if self.cur == Token::Semicolon {
            self.bump();
        }
    }

    /// Parse a raw value (used for custom properties): tokens until `;` or `}`.
    fn parse_raw_value(&mut self, _custom: bool) -> Vec<(Token<'static>, Loc)> {
        let mut out = Vec::new();
        let mut depth = 0;
        loop {
            match self.cur.clone() {
                Token::EOF => break,
                Token::Semicolon if depth == 0 => break,
                Token::CloseCurlyBracket if depth == 0 => break,
                Token::OpenCurlyBracket | Token::OpenParenthesis | Token::OpenSquareBracket => {
                    depth += 1;
                    out.push((token_static(self.cur.clone()), self.cur_start));
                    self.bump();
                }
                Token::CloseCurlyBracket | Token::CloseParenthesis | Token::CloseSquareBracket => {
                    depth -= 1;
                    out.push((token_static(self.cur.clone()), self.cur_start));
                    self.bump();
                }
                _ => {
                    out.push((token_static(self.cur.clone()), self.cur_start));
                    self.bump();
                }
            }
        }
        out
    }

    /// Parse a value into a typed Value tree.
    fn parse_value(&mut self) -> Result<Value, Error> {
        let items = self.parse_component_list()?;
        if items.is_empty() {
            return Ok(Value::Empty);
        }
        Ok(Value::CommaList(items))
    }

    /// Parse a comma-separated list of space-separated components.
    fn parse_component_list(&mut self) -> Result<Vec<Value>, Error> {
        let mut out = Vec::new();
        loop {
            let comps = self.parse_space_list()?;
            if !comps.is_empty() {
                out.push(if comps.len() == 1 {
                    comps.into_iter().next().unwrap()
                } else {
                    Value::List(comps)
                });
            }
            self.skip_ws();
            if self.cur == Token::Comma {
                self.bump();
                continue;
            }
            break;
        }
        Ok(out)
    }

    /// Parse space-separated components until `,`, `;`, `}` or EOF.
    fn parse_space_list(&mut self) -> Result<Vec<Value>, Error> {
        let mut out = Vec::new();
        loop {
            self.skip_ws();
            match self.cur.clone() {
                Token::EOF | Token::Semicolon | Token::Comma | Token::CloseCurlyBracket => break,
                _ => {
                    let v = self.parse_component()?;
                    out.push(v);
                }
            }
        }
        Ok(out)
    }

    /// Parse one component value.
    fn parse_component(&mut self) -> Result<Value, Error> {
        match self.cur.clone() {
            Token::Ident(name) => {
                self.bump();
                Ok(Value::Ident(name.to_string()))
            }
            Token::Number {
                has_sign,
                value,
                int_value,
            } => {
                self.bump();
                Ok(Value::Number(Number {
                    value,
                    int_value,
                    unit: None,
                }))
            }
            Token::Percentage {
                has_sign,
                value,
                int_value,
            } => {
                self.bump();
                Ok(Value::Number(Number {
                    value,
                    int_value,
                    unit: Some("%".to_string()),
                }))
            }
            Token::Dimension {
                has_sign,
                value,
                int_value,
                unit,
            } => {
                self.bump();
                Ok(Value::Number(Number {
                    value,
                    int_value,
                    unit: Some(unit.to_string()),
                }))
            }
            Token::Str(s) => {
                self.bump();
                Ok(Value::Str(s.to_string()))
            }
            Token::Hash { value, .. } => {
                self.bump();
                match parse_hex(value) {
                    Some((r, g, b, a)) => Ok(Value::Color(Color::Rgba(r, g, b, a))),
                    None => Ok(Value::Raw(token_text_of(
                        self.src,
                        self.cur_start,
                        self.cur_end,
                    ))),
                }
            }
            Token::UnquotedUrl(_) => {
                let start = self.cur_start;
                self.bump();
                // extract the url text
                let text = &self.src[start..self.cur_end];
                let inner = text
                    .trim_start_matches("url(")
                    .trim_end_matches(')')
                    .trim();
                Ok(Value::Url(Some(inner.to_string())))
            }
            Token::Function(name) => {
                let name = name.to_string();
                self.bump();
                self.parse_function(name)
            }
            Token::OpenParenthesis => {
                // grouped value
                self.bump();
                let inner = self.parse_space_list()?;
                let mut res = Value::Empty;
                if inner.len() == 1 {
                    res = inner.into_iter().next().unwrap();
                } else if !inner.is_empty() {
                    res = Value::List(inner);
                }
                if self.cur == Token::CloseParenthesis {
                    self.bump();
                }
                Ok(res)
            }
            _ => {
                // raw token
                let text = self.token_text();
                self.bump();
                Ok(Value::Raw(text))
            }
        }
    }

    fn parse_function(&mut self, name: String) -> Result<Value, Error> {
        match name.as_str() {
            "var" => {
                self.skip_ws();
                let custom = match self.cur.clone() {
                    Token::Ident(n) if n.starts_with("--") => {
                        self.bump();
                        n.to_string()
                    }
                    _ => {
                        // error: var() requires a custom property name
                        return Err(self.parse_error(ErrorKind::InvalidValue));
                    }
                };
                let mut fallback = None;
                self.skip_ws();
                if self.cur == Token::Comma {
                    self.bump();
                    let items = self.parse_component_list()?;
                    fallback = Some(items);
                }
                if self.cur == Token::CloseParenthesis {
                    self.bump();
                }
                Ok(Value::Var { name: custom, fallback })
            }
            "calc" | "min" | "max" | "clamp" | "round" | "mod" | "rem" | "sign" | "abs" | "hypot" => {
                self.skip_ws();
                let items = self.parse_component_list()?;
                if self.cur == Token::CloseParenthesis {
                    self.bump();
                }
                Ok(Value::Function(name, items))
            }
            _ => {
                self.skip_ws();
                let items = self.parse_component_list()?;
                if self.cur == Token::CloseParenthesis {
                    self.bump();
                }
                Ok(Value::Function(name, items))
            }
        }
    }

    fn parse_nested_at_rule(&mut self, name: &str) -> Result<NestedItem, Error> {
        let _ = name;
        Err(Error::new(
            ErrorKind::AtRuleBodyInvalid,
            &self.filename,
            self.src,
            self.cur_start,
        ))
    }
}

pub enum NestedItem {
    AtRule(Rule),
    Declaration(Declaration),
}

pub struct ParseOptions {
    pub custom_media: bool,
    pub css_modules: bool,
    pub error_recovery: bool,
}

impl Default for ParseOptions {
    fn default() -> Self {
        ParseOptions {
            custom_media: false,
            css_modules: false,
            error_recovery: false,
        }
    }
}

/// Split a selector list on top-level commas.
pub fn split_selectors(s: &str) -> Vec<Selector> {
    let mut out = Vec::new();
    let mut depth = 0;
    let mut start = 0;
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'[' | b'(' => depth += 1,
            b']' | b')' => depth -= 1,
            b',' if depth == 0 => {
                out.push(s[start..i].trim().to_string());
                start = i + 1;
            }
            _ => {}
        }
        i += 1;
    }
    out.push(s[start..].trim().to_string());
    out.into_iter()
        .map(|s| Selector { raw: s })
        .collect()
}

/// Convert a borrowed token into an owned one (for storing raw values).
pub fn token_static(t: Token<'a>) -> Token<'static>
where
    'a: 'static,
{
    unsafe { std::mem::transmute(t) }
}

pub fn token_text_of(src: &str, start: usize, end: usize) -> String {
    src[start..end.min(src.len())].to_string()
}
