//! Serializer for the stylesheet AST.

use crate::ast::*;
use crate::values::*;

pub struct Printer {
    pub minify: bool,
    pub indent: usize,
    pub out: String,
    /// Whether a declaration/rule has been emitted already in this block.
    pub wrote_something: bool,
}

impl Printer {
    pub fn new(minify: bool) -> Printer {
        Printer {
            minify,
            indent: 0,
            out: String::new(),
            wrote_something: false,
        }
    }

    pub fn indent_str(&self) -> String {
        "  ".repeat(self.indent)
    }

    pub fn newline(&mut self) {
        if self.minify {
            return;
        }
        self.out.push('\n');
        self.out.push_str(&self.indent_str());
    }

    pub fn newline_only(&mut self) {
        if self.minify {
            return;
        }
        self.out.push('\n');
    }

    /// Serialize a stylesheet.
    pub fn stylesheet(&mut self, sheet: &Stylesheet) {
        for (i, rule) in sheet.rules.iter().enumerate() {
            if i > 0 {
                self.blank_line();
            }
            self.rule(rule, true);
        }
        if self.minify {
            self.out.push('\n');
        } else {
            self.out.push_str("\n\n");
        }
    }

    fn blank_line(&mut self) {
        if self.minify {
            return;
        }
        if !self.out.is_empty() {
            // the previous rule ended with "\n\n"; nothing to do
        }
    }

    pub fn rule(&mut self, rule: &Rule, top: bool) {
        match rule {
            Rule::Style {
                selectors,
                block,
            } => {
                self.selectors(selectors);
                self.declaration_block(block);
            }
            Rule::Nesting {
                selectors,
                block,
            } => {
                self.out.push_str("& ");
                self.selectors(selectors);
                self.declaration_block(block);
            }
            Rule::Media { query, rules } => {
                self.out.push_str("@media ");
                self.media_queries(query);
                self.block_rules(rules);
            }
            Rule::Supports { condition, rules } => {
                self.out.push_str("@supports ");
                self.out.push_str(condition);
                self.block_rules(rules);
            }
            Rule::Import {
                url,
                media,
                supports,
                layer,
            } => {
                self.out.push_str("@import ");
                serialize_string(url, &mut self.out);
                if let Some(s) = supports {
                    self.out.push_str(" supports ");
                    self.out.push_str(s);
                }
                if let Some(l) = layer {
                    if !l.is_empty() {
                        self.out.push_str(" layer");
                        if l.len() != 1 || l[0] != "" {
                            self.out.push('(');
                            for (i, n) in l.iter().enumerate() {
                                if i > 0 {
                                    self.out.push_str(if self.minify { "," } else { ", " });
                                }
                                self.out.push_str(n);
                            }
                            self.out.push(')');
                        }
                    }
                }
                if let Some(m) = media {
                    self.out.push(' ');
                    self.media_queries(m);
                }
                self.out.push(';');
            }
            Rule::Charset(c) => {
                self.out.push_str("@charset ");
                serialize_string(c, &mut self.out);
                self.out.push(';');
            }
            Rule::Keyframes {
                name,
                keyframes,
            } => {
                self.out.push_str("@keyframes ");
                self.out.push_str(name);
                self.block_keyframes(keyframes);
            }
            Rule::FontFace { block } => {
                self.out.push_str("@font-face");
                self.block_decls(block);
            }
            Rule::Page { selectors, block } => {
                self.out.push_str("@page");
                for s in selectors {
                    self.out.push(' ');
                    self.out.push_str(s);
                }
                self.block_decls(block);
            }
            Rule::Namespace { prefix, url } => {
                self.out.push_str("@namespace ");
                if let Some(p) = prefix {
                    self.out.push_str(p);
                    self.out.push(' ');
                }
                if let Some(u) = url {
                    serialize_string(u, &mut self.out);
                }
                self.out.push(';');
            }
            Rule::CounterStyle { name, block } => {
                self.out.push_str("@counter-style ");
                self.out.push_str(name);
                self.block_decls(block);
            }
            Rule::Property { name, block } => {
                self.out.push_str("@property ");
                self.out.push_str(name);
                self.block_decls(block);
            }
            Rule::Layer { name, rules } => {
                self.out.push_str("@layer ");
                if name.is_empty() {
                    self.out.push(';');
                    return;
                }
                for (i, n) in name.iter().enumerate() {
                    if i > 0 {
                        self.out.push_str(if self.minify { "," } else { ", " });
                    }
                    self.out.push_str(n);
                }
                if rules.is_empty() {
                    self.out.push(';');
                } else {
                    self.block_rules(rules);
                }
            }
            Rule::Container {
                name,
                condition,
                rules,
            } => {
                self.out.push_str("@container");
                if let Some(n) = name {
                    self.out.push(' ');
                    self.out.push_str(n);
                }
                if let Some(c) = condition {
                    self.out.push(' ');
                    self.out.push_str(c);
                }
                self.block_rules(rules);
            }
            Rule::Scope { prelude, rules } => {
                self.out.push_str("@scope");
                if let Some(p) = prelude {
                    self.out.push(' ');
                    self.out.push_str(p);
                }
                self.block_rules(rules);
            }
            Rule::FontPaletteValues { name, block } => {
                self.out.push_str("@font-palette-values ");
                self.out.push_str(name);
                self.block_decls(block);
            }
            Rule::Unknown {
                name,
                prelude,
                block,
            } => {
                self.out.push('@');
                self.out.push_str(name);
                if !prelude.is_empty() {
                    self.out.push(' ');
                    self.out.push_str(prelude);
                }
                match block {
                    Some(b) => {
                        self.out.push_str(" {");
                        if !self.minify {
                            self.out.push('\n');
                            for line in b.lines() {
                                if line.trim().is_empty() {
                                    continue;
                                }
                                self.out.push_str("  ");
                                self.out.push_str(&self.indent_str());
                                self.out.push_str(line.trim());
                                self.out.push('\n');
                            }
                            self.out.push_str(&self.indent_str());
                            self.out.push('}');
                        } else {
                            self.out.push_str(b);
                            self.out.push('}');
                        }
                    }
                    None => self.out.push(';'),
                }
            }
        }
    }

    fn block_rules(&mut self, rules: &[Rule]) {
        self.out.push_str(" {");
        if self.minify {
            for r in rules {
                self.rule(r, false);
            }
        } else {
            self.indent += 1;
            for (i, r) in rules.iter().enumerate() {
                if i > 0 {
                    self.out.push('\n');
                    self.out.push('\n');
                    self.out.push_str(&self.indent_str());
                } else {
                    self.out.push('\n');
                    self.out.push_str(&self.indent_str());
                }
                self.rule(r, false);
            }
            self.indent -= 1;
            self.newline();
        }
        self.out.push('}');
    }

    fn block_keyframes(&mut self, kfs: &[(Vec<Selector>, DeclarationBlock)]) {
        self.out.push_str(" {");
        if self.minify {
            for (sels, block) in kfs {
                self.selectors(sels);
                self.declaration_block(block);
            }
        } else {
            self.indent += 1;
            for (i, (sels, block)) in kfs.iter().enumerate() {
                if i > 0 {
                    self.out.push_str("\n\n");
                    self.out.push_str(&self.indent_str());
                } else {
                    self.out.push('\n');
                    self.out.push_str(&self.indent_str());
                }
                self.selectors(sels);
                self.declaration_block_inner(block);
            }
            self.indent -= 1;
            self.newline();
        }
        self.out.push('}');
    }

    fn block_decls(&mut self, block: &DeclarationBlock) {
        self.out.push_str(" {");
        if self.minify {
            self.declaration_block_inner(block);
        } else {
            self.indent += 1;
            self.out.push('\n');
            self.out.push_str(&self.indent_str());
            self.declaration_block_inner(block);
            self.indent -= 1;
            self.newline();
        }
        self.out.push('}');
    }

    fn declaration_block(&mut self, block: &DeclarationBlock) {
        self.out.push_str(" {");
        self.out.push('\n');
        if self.minify {
            self.declaration_block_inner(block);
        } else {
            self.indent += 1;
            self.out.push_str(&self.indent_str());
            self.declaration_block_inner(block);
            self.indent -= 1;
            self.newline();
        }
        self.out.push('}');
    }

    fn declaration_block_inner(&mut self, block: &DeclarationBlock) {
        for (i, d) in block.declarations.iter().enumerate() {
            if i > 0 && !self.minify {
                self.newline();
            }
            self.declaration(d);
        }
        if !block.rules.is_empty() {
            if self.minify {
                for r in &block.rules {
                    self.rule(r, false);
                }
            } else {
                for r in &block.rules {
                    self.out.push('\n');
                    self.out.push('\n');
                    self.out.push_str(&self.indent_str());
                    self.rule(r, false);
                }
            }
        }
    }

    fn declaration(&mut self, d: &Declaration) {
        self.out.push_str(&d.property);
        if self.minify {
            self.out.push(':');
        } else {
            self.out.push_str(": ");
        }
        self.value(&d.value);
        if d.important {
            self.out.push_str(if self.minify {
                "!important"
            } else {
                " !important"
            });
        }
        self.out.push(';');
    }

    pub fn value(&mut self, v: &Value) {
        match v {
            Value::Number(n) => self.number(n),
            Value::Color(c) => serialize_color(c, self.minify, &mut self.out),
            Value::Ident(s) => self.out.push_str(s),
            Value::Str(s) => serialize_string(s, &mut self.out),
            Value::Url(Some(u)) => {
                if self.minify && can_unquote(u) {
                    self.out.push_str("url(");
                    self.out.push_str(u);
                    self.out.push(')');
                } else {
                    self.out.push_str("url(");
                    serialize_string(u, &mut self.out);
                    self.out.push(')');
                }
            }
            Value::Url(None) => self.out.push_str("url()"),
            Value::Function(name, args) => {
                self.out.push_str(name);
                self.out.push('(');
                for (i, a) in args.iter().enumerate() {
                    if i > 0 {
                        self.out.push(',');
                    }
                    self.value(a);
                }
                self.out.push(')');
            }
            Value::Var { name, fallback } => {
                self.out.push_str("var(");
                self.out.push_str(name);
                if let Some(f) = fallback {
                    self.out.push_str(if self.minify { "," } else { ", " });
                    for (i, a) in f.iter().enumerate() {
                        if i > 0 {
                            self.out.push(',');
                        }
                        self.value(a);
                    }
                }
                self.out.push(')');
            }
            Value::Calc(items) => {
                for (i, it) in items.iter().enumerate() {
                    if i > 0 && !self.minify {
                        self.out.push(' ');
                    }
                    self.value(it);
                }
            }
            Value::List(items) => {
                for (i, it) in items.iter().enumerate() {
                    if i > 0 && !self.minify {
                        self.out.push(' ');
                    }
                    self.value(it);
                }
            }
            Value::CommaList(items) => {
                for (i, it) in items.iter().enumerate() {
                    if i > 0 {
                        self.out.push_str(if self.minify { "," } else { ", " });
                    }
                    self.value(it);
                }
            }
            Value::Raw(items) => {
                for (i, it) in items.iter().enumerate() {
                    if i == 0 {
                        self.out.push_str(it.trim_start());
                        continue;
                    }
                    if i == items.len() - 1 {
                        // trailing whitespace handled below
                        self.out.push_str(it.trim_end());
                        continue;
                    }
                    self.out.push_str(it);
                }
            }
            Value::Empty => {}
        }
    }

    pub fn number(&mut self, n: &Number) {
        serialize_number(n.value, n.int_value, &mut self.out);
        if let Some(u) = &n.unit {
            self.out.push_str(u);
        }
    }

    pub fn selectors(&mut self, sels: &[Selector]) {
        for (i, s) in sels.iter().enumerate() {
            if i > 0 {
                self.out.push_str(if self.minify { "," } else { ", " });
            }
            self.selector(s);
        }
    }

    pub fn selector(&mut self, s: &Selector) {
        for p in &s.parts {
            match p {
                SelectorPart::Text(t) => self.out.push_str(t),
                SelectorPart::WhiteSpace(w) => {
                    if !self.minify {
                        self.out.push_str(" ");
                    }
                }
                SelectorPart::Comment(_) => {}
            }
        }
    }

    pub fn media_queries(&mut self, qs: &[MediaQuery]) {
        for (i, q) in qs.iter().enumerate() {
            if i > 0 {
                self.out.push_str(if self.minify { "," } else { ", " });
            }
            self.media_query(q);
        }
    }

    fn media_query(&mut self, q: &MediaQuery) {
        match q {
            MediaQuery::Ident {
                modifier,
                media_type,
            } => {
                if let Some(m) = modifier {
                    self.out.push_str(m);
                    self.out.push(' ');
                    if self.minify {
                        self.out.pop();
                    }
                }
                self.out.push_str(media_type);
            }
            MediaQuery::Feature {
                name,
                value,
                op,
                ..
            } => {
                self.out.push('(');
                self.out.push_str(name);
                if let Some(v) = value {
                    match op {
                        None => {
                            self.out.push(':');
                            if !self.minify {
                                self.out.push(' ');
                            }
                        }
                        Some(op) => {
                            let o = match op {
                                MediaQueryOp::Eq => "=",
                                MediaQueryOp::Ne => "!=",
                                MediaQueryOp::Lt => "<",
                                MediaQueryOp::Le => "<=",
                                MediaQueryOp::Gt => ">",
                                MediaQueryOp::Ge => ">=",
                            };
                            self.out.push(' ');
                            self.out.push_str(o);
                            self.out.push(' ');
                            if self.minify {
                                self.out = self.out.trim_end().to_string();
                            }
                        }
                    }
                    self.out.push_str(v);
                }
                self.out.push(')');
            }
            MediaQuery::Operation(a, and, b) => {
                self.media_query(a);
                self.out.push_str(if *and {
                    if self.minify {
                        "and"
                    } else {
                        " and "
                    }
                } else {
                    if self.minify {
                        "or"
                    } else {
                        " or "
                    }
                });
                if !self.minify {
                    self.out.push(' ');
                }
                self.media_query(b);
            }
            MediaQuery::Not(m) => {
                self.out.push_str("not ");
                if !self.minify {
                    self.out.push(' ');
                }
                self.media_query(m);
            }
        }
    }
}

pub fn can_unquote(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    let mut chars = s.chars();
    let first = chars.next().unwrap();
    if !(first.is_alphabetic() || first == '_' || first == '-') {
        return false;
    }
    for c in chars {
        if !(c.is_alphanumeric() || c == '_' || c == '-' || c >= '\u{80}') {
            return false;
        }
    }
    true
}
