//! CSS parser.

use crate::ast::*;
use crate::error::{Error, ErrorKind};
use crate::token::{Token, Tokenizer};
use crate::values::*;

pub struct Parser<'a> {
    pub src: &'a str,
    pub tok: Tokenizer<'a>,
    pub cur: Token<'a>,
    pub cur_start: usize,
    pub cur_end: usize,
    pub filename: String,
    pub custom_media: bool,
    pub error_recovery: bool,
    pub errors: Vec<String>,
}

impl<'a> Parser<'a> {
    pub fn new(src: &'a str, filename: &str, custom_media: bool, error_recovery: bool) -> Parser<'a> {
        let mut tok = Tokenizer::new(src);
        let (cur, s, e) = tok.next();
        Parser {
            src,
            tok,
            cur,
            cur_start: s,
            cur_end: e,
            filename: filename.to_string(),
            custom_media,
            error_recovery,
            errors: Vec::new(),
        }
    }

    fn bump(&mut self) {
        let (t, s, e) = self.tok.next();
        self.cur = t;
        self.cur_start = s;
        self.cur_end = e;
    }

    fn skip_ws(&mut self) {
        while self.cur.is_whitespace_or_comment() {
            self.bump();
        }
    }

    fn text(&self) -> String {
        self.src[self.cur_start..self.cur_end.min(self.src.len())].to_string()
    }

    fn save(&self) -> (usize, Token<'a>, usize, usize) {
        (
            self.tok.position(),
            self.cur.clone(),
            self.cur_start,
            self.cur_end,
        )
    }

    fn restore(&mut self, s: (usize, Token<'a>, usize, usize)) {
        self.tok.set_position(s.0);
        let (t, a, b) = self.tok.next();
        self.cur = t;
        self.cur_start = a;
        self.cur_end = b;
        let _ = s;
    }

    fn err(&self, kind: ErrorKind) -> Error {
        Error::new(kind, &self.filename, self.src, self.cur_start)
    }

    // ---------------------------------------------------------------- top level

    pub fn parse_stylesheet(&mut self) -> Result<Stylesheet, Error> {
        let mut rules = Vec::new();
        loop {
            self.skip_ws();
            if self.cur.is_eof() {
                break;
            }
            match self.parse_rule() {
                Ok(Some(r)) => rules.push(r),
                Ok(None) => {}
                Err(e) => {
                    if self.error_recovery {
                        self.errors.push(e.to_message());
                        self.skip_to_rule_end();
                        continue;
                    }
                    return Err(e);
                }
            }
        }
        Ok(Stylesheet { rules })
    }

    fn skip_to_rule_end(&mut self) {
        let mut depth = 0;
        loop {
            match self.cur.clone() {
                Token::EOF => break,
                Token::OpenCurlyBracket => {
                    depth += 1;
                    self.bump();
                }
                Token::CloseCurlyBracket => {
                    depth -= 1;
                    self.bump();
                    if depth <= 0 {
                        break;
                    }
                }
                Token::Semicolon if depth == 0 => {
                    self.bump();
                    break;
                }
                _ => self.bump(),
            }
        }
    }

    fn parse_rule(&mut self) -> Result<Option<Rule>, Error> {
        match self.cur.clone() {
            Token::AtKeyword(name) => {
                let name = name.to_string();
                self.bump();
                self.parse_at_rule(&name)
            }
            Token::EOF => Ok(None),
            _ => self.parse_qualified_rule(),
        }
    }

    /// A qualified rule: selector prelude followed by a declaration block.
    fn parse_qualified_rule(&mut self) -> Result<Option<Rule>, Error> {
        let selectors = self.parse_selectors()?;
        self.skip_ws();
        if self.cur != Token::OpenCurlyBracket {
            return Err(self.err(ErrorKind::EndOfInput));
        }
        self.bump();
        let block = self.parse_declaration_block()?;
        Ok(Some(Rule::Style { selectors, block }))
    }

    /// Parse a selector prelude up to (but not including) `{`.
    fn parse_selectors(&mut self) -> Result<Vec<Selector>, Error> {
        let mut out: Vec<Selector> = Vec::new();
        let mut cur: Vec<SelectorPart> = Vec::new();
        let mut depth = 0usize;
        loop {
            match self.cur.clone() {
                Token::EOF => {
                    return Err(Error::new(
                        ErrorKind::EndOfInput,
                        &self.filename,
                        self.src,
                        self.cur_start,
                    ))
                }
                Token::OpenCurlyBracket if depth == 0 => break,
                Token::OpenSquareBracket | Token::OpenParenthesis => {
                    depth += 1;
                    cur.push(SelectorPart::Text(self.text()));
                    self.bump();
                }
                Token::CloseSquareBracket | Token::CloseParenthesis => {
                    depth -= 1;
                    cur.push(SelectorPart::Text(self.text()));
                    self.bump();
                }
                Token::Comma if depth == 0 => {
                    self.bump();
                    out.push(Selector { parts: std::mem::take(&mut cur) });
                }
                Token::WhiteSpace => {
                    let t = self.text();
                    self.bump();
                    if !cur.is_empty() {
                        cur.push(SelectorPart::WhiteSpace(t));
                    }
                }
                Token::Comment(c) => {
                    let t = format!("/*{}*/", c);
                    self.bump();
                    cur.push(SelectorPart::Comment(t));
                }
                Token::Str(s) => {
                    // Attribute selector values: quotes are removed when the
                    // value is a valid identifier.
                    let mut t = String::new();
                    if is_ident_string(&s) {
                        t.push_str(&s);
                    } else {
                        serialize_string(&s, &mut t);
                    }
                    self.bump();
                    cur.push(SelectorPart::Text(t));
                }
                _ => {
                    let t = self.text();
                    self.bump();
                    cur.push(SelectorPart::Text(t));
                }
            }
        }
        // trim trailing whitespace
        while matches!(cur.last(), Some(SelectorPart::WhiteSpace(_))) {
            cur.pop();
        }
        while matches!(cur.first(), Some(SelectorPart::WhiteSpace(_))) {
            cur.remove(0);
        }
        out.push(Selector { parts: cur });
        Ok(out)
    }

    // ---------------------------------------------------------------- at-rules

    fn parse_at_rule(&mut self, name: &str) -> Result<Option<Rule>, Error> {
        match name {
            "media" => {
                let query = self.parse_media_query_list()?;
                self.skip_ws();
                if self.cur != Token::OpenCurlyBracket {
                    return Err(self.err(ErrorKind::AtRuleBodyInvalid));
                }
                self.bump();
                let rules = self.parse_rules_until_close()?;
                Ok(Some(Rule::Media { query, rules }))
            }
            "supports" => {
                let condition = self.parse_supports_condition()?;
                self.skip_ws();
                if self.cur != Token::OpenCurlyBracket {
                    return Err(self.err(ErrorKind::AtRuleBodyInvalid));
                }
                self.bump();
                let rules = self.parse_rules_until_close()?;
                Ok(Some(Rule::Supports { condition, rules }))
            }
            "import" => {
                self.skip_ws();
                let url = match self.cur.clone() {
                    Token::Str(s) => {
                        self.bump();
                        s.to_string()
                    }
                    Token::Function(n) if n == "url" => {
                        self.bump();
                        self.skip_ws();
                        let u = match self.cur.clone() {
                            Token::Str(s) => {
                                self.bump();
                                s
                            }
                            Token::UnquotedUrl(u) => {
                                self.bump();
                                u.to_string()
                            }
                            _ => return Err(self.err(ErrorKind::InvalidValue)),
                        };
                        self.skip_ws();
                        if self.cur == Token::CloseParenthesis {
                            self.bump();
                        }
                        u
                    }
                    _ => return Err(self.err(ErrorKind::InvalidValue)),
                };
                let mut supports = None;
                let mut layer = None;
                let mut media = None;
                loop {
                    self.skip_ws();
                    if let Token::Ident(id) = self.cur.clone() {
                        match id.as_str() {
                            "supports" => {
                                self.bump();
                                self.skip_ws();
                                if self.cur == Token::OpenParenthesis {
                                    let start = self.cur_start;
                                    let mut depth = 0;
                                    loop {
                                        match self.cur.clone() {
                                            Token::EOF => break,
                                            Token::OpenParenthesis => depth += 1,
                                            Token::CloseParenthesis => {
                                                depth -= 1;
                                                if depth == 0 {
                                                    self.bump();
                                                    break;
                                                }
                                            }
                                            _ => {}
                                        }
                                        self.bump();
                                    }
                                    supports = Some(self.src[start..self.cur_start].to_string());
                                } else {
                                    let c = self.parse_supports_condition()?;
                                    supports = Some(format!("({})", c));
                                }
                                continue;
                            }
                            "layer" => {
                                self.bump();
                                self.skip_ws();
                                if self.cur == Token::OpenParenthesis {
                                    self.bump();
                                    let mut names = Vec::new();
                                    loop {
                                        self.skip_ws();
                                        match self.cur.clone() {
                                            Token::Ident(n) => {
                                                names.push(n.to_string());
                                                self.bump();
                                            }
                                            Token::Comma => {
                                                self.bump();
                                            }
                                            Token::CloseParenthesis => {
                                                self.bump();
                                                break;
                                            }
                                            Token::EOF => break,
                                            _ => self.bump(),
                                        }
                                    }
                                    layer = Some(names);
                                } else {
                                    layer = Some(Vec::new());
                                }
                                continue;
                            }
                            _ => {}
                        }
                    }
                    if self.cur == Token::Semicolon {
                        break;
                    }
                    if self.cur.is_eof() || self.cur == Token::CloseCurlyBracket {
                        break;
                    }
                    // media query list
                    let q = self.parse_media_query_list()?;
                    media = Some(q);
                    break;
                }
                self.skip_ws();
                if self.cur == Token::Semicolon {
                    self.bump();
                }
                Ok(Some(Rule::Import {
                    url,
                    media,
                    supports,
                    layer,
                }))
            }
            "charset" => {
                self.skip_ws();
                let c = match self.cur.clone() {
                    Token::Str(s) => {
                        self.bump();
                        s
                    }
                    _ => String::new(),
                };
                self.skip_ws();
                if self.cur == Token::Semicolon {
                    self.bump();
                }
                Ok(Some(Rule::Charset(c)))
            }
            "font-face" => {
                self.skip_ws();
                if self.cur != Token::OpenCurlyBracket {
                    return Err(self.err(ErrorKind::AtRuleBodyInvalid));
                }
                self.bump();
                let block = self.parse_declaration_block()?;
                Ok(Some(Rule::FontFace { block }))
            }
            "page" => {
                let mut selectors = Vec::new();
                let mut buf = String::new();
                loop {
                    self.skip_ws();
                    match self.cur.clone() {
                        Token::OpenCurlyBracket | Token::EOF => break,
                        _ => {
                            buf.push_str(&self.text());
                            self.bump();
                        }
                    }
                }
                if !buf.trim().is_empty() {
                    selectors.push(buf.trim().to_string());
                }
                if self.cur != Token::OpenCurlyBracket {
                    return Err(self.err(ErrorKind::AtRuleBodyInvalid));
                }
                self.bump();
                let block = self.parse_declaration_block()?;
                Ok(Some(Rule::Page { selectors, block }))
            }
            "keyframes" | "-webkit-keyframes" | "-moz-keyframes" | "-ms-keyframes"
            | "-o-keyframes" => {
                self.skip_ws();
                let kf_name = match self.cur.clone() {
                    Token::Ident(n) => {
                        self.bump();
                        n.to_string()
                    }
                    Token::Str(s) => {
                        self.bump();
                        s
                    }
                    _ => return Err(self.err(ErrorKind::InvalidValue)),
                };
                self.skip_ws();
                if self.cur != Token::OpenCurlyBracket {
                    return Err(self.err(ErrorKind::AtRuleBodyInvalid));
                }
                self.bump();
                let mut kfs = Vec::new();
                loop {
                    self.skip_ws();
                    match self.cur.clone() {
                        Token::EOF | Token::CloseCurlyBracket => break,
                        _ => {
                            let sels = self.parse_keyframe_selectors()?;
                            self.skip_ws();
                            if self.cur != Token::OpenCurlyBracket {
                                return Err(self.err(ErrorKind::AtRuleBodyInvalid));
                            }
                            self.bump();
                            let block = self.parse_declaration_block()?;
                            kfs.push((sels, block));
                        }
                    }
                }
                if self.cur == Token::CloseCurlyBracket {
                    self.bump();
                }
                Ok(Some(Rule::Keyframes {
                    name: kf_name,
                    keyframes: kfs,
                }))
            }
            "namespace" => {
                self.skip_ws();
                let mut prefix = None;
                let mut url = None;
                if let Token::Ident(n) = self.cur.clone() {
                    if !n.starts_with('"') {
                        // could be a prefix or a url
                        let save = self.save();
                        self.bump();
                        self.skip_ws();
                        match self.cur.clone() {
                            Token::Str(s) => {
                                prefix = Some(n.to_string());
                                url = Some(s);
                                self.bump();
                            }
                            Token::Function(fn_) if fn_ == "url" => {
                                prefix = Some(n.to_string());
                                self.bump();
                                self.skip_ws();
                                let u = match self.cur.clone() {
                                    Token::Str(s) => {
                                        self.bump();
                                        s
                                    }
                                    Token::UnquotedUrl(u) => {
                                        self.bump();
                                        u.to_string()
                                    }
                                    _ => String::new(),
                                };
                                self.skip_ws();
                                if self.cur == Token::CloseParenthesis {
                                    self.bump();
                                }
                                url = Some(u);
                            }
                            _ => {
                                self.restore(save);
                                let u = match self.cur.clone() {
                                    Token::Str(s) => {
                                        self.bump();
                                        s
                                    }
                                    _ => return Err(self.err(ErrorKind::InvalidValue)),
                                };
                                url = Some(u);
                            }
                        }
                    }
                } else {
                    match self.cur.clone() {
                        Token::Str(s) => {
                            self.bump();
                            url = Some(s);
                        }
                        Token::Function(n) if n == "url" => {
                            self.bump();
                            self.skip_ws();
                            let u = match self.cur.clone() {
                                Token::Str(s) => {
                                    self.bump();
                                    s
                                }
                                Token::UnquotedUrl(u) => {
                                    self.bump();
                                    u.to_string()
                                }
                                _ => String::new(),
                            };
                            self.skip_ws();
                            if self.cur == Token::CloseParenthesis {
                                self.bump();
                            }
                            url = Some(u);
                        }
                        _ => {}
                    }
                }
                self.skip_ws();
                if self.cur == Token::Semicolon {
                    self.bump();
                }
                Ok(Some(Rule::Namespace { prefix, url }))
            }
            "layer" => {
                self.skip_ws();
                if self.cur == Token::OpenCurlyBracket {
                    self.bump();
                    let rules = self.parse_rules_until_close()?;
                    return Ok(Some(Rule::Layer {
                        name: Vec::new(),
                        rules,
                    }));
                }
                let mut names = Vec::new();
                loop {
                    self.skip_ws();
                    match self.cur.clone() {
                        Token::Ident(n) => {
                            names.push(n.to_string());
                            self.bump();
                        }
                        Token::Delim('.') => {
                            self.bump();
                            if let Token::Ident(n) = self.cur.clone() {
                                let last = names.len();
                                if last > 0 {
                                    let idx = last - 1;
                                    names[idx].push('.');
                                    names[idx].push_str(&n);
                                } else {
                                    names.push(n.to_string());
                                }
                                self.bump();
                            }
                        }
                        Token::Comma => {
                            self.bump();
                        }
                        _ => break,
                    }
                }
                self.skip_ws();
                if self.cur == Token::OpenCurlyBracket {
                    self.bump();
                    let rules = self.parse_rules_until_close()?;
                    Ok(Some(Rule::Layer { name: names, rules }))
                } else {
                    if self.cur == Token::Semicolon {
                        self.bump();
                    }
                    Ok(Some(Rule::Layer {
                        name: names,
                        rules: Vec::new(),
                    }))
                }
            }
            "container" => {
                self.skip_ws();
                let mut nm = None;
                if let Token::Ident(n) = self.cur.clone() {
                    // A name, unless followed by `(` (a condition)
                    let save = self.save();
                    self.bump();
                    self.skip_ws();
                    if self.cur == Token::OpenParenthesis {
                        self.restore(save);
                    } else {
                        nm = Some(n.to_string());
                    }
                }
                let mut cond = None;
                self.skip_ws();
                if self.cur == Token::OpenParenthesis {
                    let start = self.cur_start;
                    let mut depth = 0;
                    loop {
                        match self.cur.clone() {
                            Token::EOF => break,
                            Token::OpenParenthesis => depth += 1,
                            Token::CloseParenthesis => {
                                depth -= 1;
                                if depth == 0 {
                                    self.bump();
                                    break;
                                }
                            }
                            _ => {}
                        }
                        self.bump();
                    }
                    cond = Some(normalize_container_condition(
                        &self.src[start..self.cur_start],
                    ));
                }
                self.skip_ws();
                if self.cur != Token::OpenCurlyBracket {
                    return Err(self.err(ErrorKind::AtRuleBodyInvalid));
                }
                self.bump();
                let rules = self.parse_rules_until_close()?;
                Ok(Some(Rule::Container {
                    name: nm,
                    condition: cond,
                    rules,
                }))
            }
            "scope" => {
                self.skip_ws();
                let mut prelude = None;
                if self.cur == Token::OpenParenthesis {
                    let start = self.cur_start;
                    let mut depth = 0;
                    loop {
                        match self.cur.clone() {
                            Token::EOF => break,
                            Token::OpenParenthesis => depth += 1,
                            Token::CloseParenthesis => {
                                depth -= 1;
                                if depth == 0 {
                                    self.bump();
                                    break;
                                }
                            }
                            _ => {}
                        }
                        self.bump();
                    }
                    prelude = Some(self.src[start..self.cur_start].trim().to_string());
                }
                self.skip_ws();
                if self.cur != Token::OpenCurlyBracket {
                    return Err(self.err(ErrorKind::AtRuleBodyInvalid));
                }
                self.bump();
                let rules = self.parse_rules_until_close()?;
                Ok(Some(Rule::Scope { prelude, rules }))
            }
            "property" => {
                self.skip_ws();
                let nm = match self.cur.clone() {
                    Token::Ident(n) => {
                        self.bump();
                        n.to_string()
                    }
                    _ => return Err(self.err(ErrorKind::InvalidValue)),
                };
                self.skip_ws();
                if self.cur != Token::OpenCurlyBracket {
                    return Err(self.err(ErrorKind::AtRuleBodyInvalid));
                }
                self.bump();
                let block = self.parse_declaration_block()?;
                Ok(Some(Rule::Property { name: nm, block }))
            }
            "counter-style" => {
                self.skip_ws();
                let nm = match self.cur.clone() {
                    Token::Ident(n) => {
                        self.bump();
                        n.to_string()
                    }
                    _ => return Err(self.err(ErrorKind::InvalidValue)),
                };
                self.skip_ws();
                if self.cur != Token::OpenCurlyBracket {
                    return Err(self.err(ErrorKind::AtRuleBodyInvalid));
                }
                self.bump();
                let block = self.parse_declaration_block()?;
                Ok(Some(Rule::CounterStyle { name: nm, block }))
            }
            "nest" => {
                let selectors = self.parse_selectors()?;
                self.skip_ws();
                if self.cur != Token::OpenCurlyBracket {
                    return Err(self.err(ErrorKind::AtRuleBodyInvalid));
                }
                self.bump();
                let block = self.parse_declaration_block()?;
                Ok(Some(Rule::Nesting { selectors, block }))
            }
            "font-palette-values" => {
                self.skip_ws();
                let nm = match self.cur.clone() {
                    Token::Ident(n) => {
                        self.bump();
                        n.to_string()
                    }
                    _ => return Err(self.err(ErrorKind::InvalidValue)),
                };
                self.skip_ws();
                if self.cur != Token::OpenCurlyBracket {
                    return Err(self.err(ErrorKind::AtRuleBodyInvalid));
                }
                self.bump();
                let block = self.parse_declaration_block()?;
                Ok(Some(Rule::FontPaletteValues { name: nm, block }))
            }
            _ => {
                // Unknown at-rule: preserve the prelude and block verbatim.
                let mut prelude = String::new();
                let mut depth = 0i32;
                let mut block = None;
                loop {
                    self.skip_ws();
                    match self.cur.clone() {
                        Token::EOF => break,
                        Token::OpenCurlyBracket => {
                            depth += 1;
                            if depth == 1 {
                                self.bump();
                                let start = self.cur_start;
                                let mut d2 = 0;
                                loop {
                                    self.skip_ws_incl();
                                    match self.cur.clone() {
                                        Token::EOF => break,
                                        Token::OpenCurlyBracket => {
                                            d2 += 1;
                                            self.bump();
                                        }
                                        Token::CloseCurlyBracket => {
                                            if d2 == 0 {
                                                let b = self.src[start..self.cur_start].to_string();
                                                self.bump();
                                                block = Some(b);
                                                break;
                                            }
                                            d2 -= 1;
                                            self.bump();
                                        }
                                        _ => self.bump(),
                                    }
                                }
                                break;
                            }
                        }
                        Token::Semicolon if depth == 0 => {
                            self.bump();
                            break;
                        }
                        _ => {
                            prelude.push_str(&self.text());
                            self.bump();
                        }
                    }
                }
                Ok(Some(Rule::Unknown {
                    name: name.to_string(),
                    prelude: prelude.trim().to_string(),
                    block,
                }))
            }
        }
    }

    /// Skip whitespace and comments (helper that also skips comments).
    fn skip_ws_incl(&mut self) {
        self.skip_ws();
    }

    /// Parse a list of rules until the matching `}`.
    fn parse_rules_until_close(&mut self) -> Result<Vec<Rule>, Error> {
        let mut rules = Vec::new();
        loop {
            self.skip_ws();
            match self.cur.clone() {
                Token::EOF | Token::CloseCurlyBracket => break,
                _ => match self.parse_rule() {
                    Ok(Some(r)) => rules.push(r),
                    Ok(None) => break,
                    Err(e) => {
                        if self.error_recovery {
                            self.errors.push(e.to_message());
                            self.skip_to_rule_end();
                            continue;
                        }
                        return Err(e);
                    }
                },
            }
        }
        if self.cur == Token::CloseCurlyBracket {
            self.bump();
        }
        Ok(rules)
    }

    fn parse_keyframe_selectors(&mut self) -> Result<Vec<Selector>, Error> {
        let mut out = Vec::new();
        let mut cur: Vec<SelectorPart> = Vec::new();
        loop {
            self.skip_ws();
            match self.cur.clone() {
                Token::Comma => {
                    self.bump();
                    out.push(Selector {
                        parts: std::mem::take(&mut cur),
                    });
                }
                Token::OpenCurlyBracket | Token::EOF | Token::CloseCurlyBracket => break,
                Token::WhiteSpace => {
                    let t = self.text();
                    self.bump();
                    if !cur.is_empty() {
                        cur.push(SelectorPart::WhiteSpace(t));
                    }
                }
                _ => {
                    let t = self.text();
                    self.bump();
                    cur.push(SelectorPart::Text(t));
                }
            }
        }
        while matches!(cur.last(), Some(SelectorPart::WhiteSpace(_))) {
            cur.pop();
        }
        out.push(Selector { parts: cur });
        Ok(out)
    }

    fn parse_supports_condition(&mut self) -> Result<String, Error> {
        let mut out = String::new();
        let mut depth = 0i32;
        loop {
            match self.cur.clone() {
                Token::EOF | Token::OpenCurlyBracket if depth == 0 => break,
                Token::OpenParenthesis => {
                    depth += 1;
                    out.push('(');
                    self.bump();
                    self.skip_ws();
                }
                Token::CloseParenthesis => {
                    depth -= 1;
                    out.push(')');
                    self.bump();
                    if depth == 0 {
                        break;
                    }
                    self.skip_ws();
                }
                Token::WhiteSpace => {
                    self.bump();
                    if depth > 0 {
                        out.push(' ');
                    }
                }
                Token::Delim(c) => {
                    out.push(c);
                    self.bump();
                }
                Token::Ident(s) => {
                    out.push_str(s);
                    self.bump();
                    // A declaration inside `supports (...)` needs a colon
                    self.skip_ws();
                    if self.cur == Token::Colon {
                        out.push(':');
                        self.bump();
                        self.skip_ws();
                    }
                }
                _ => {
                    out.push_str(&self.text());
                    self.bump();
                }
            }
        }
        Ok(out.trim().to_string())
    }

    fn parse_media_query_list(&mut self) -> Result<Vec<MediaQuery>, Error> {
        let mut out = Vec::new();
        loop {
            self.skip_ws();
            if self.cur == Token::Semicolon
                || self.cur.is_eof()
                || self.cur == Token::CloseCurlyBracket
                || self.cur == Token::OpenCurlyBracket
            {
                break;
            }
            let q = self.parse_media_query()?;
            out.push(q);
            self.skip_ws();
            if self.cur == Token::Comma {
                self.bump();
                continue;
            }
            break;
        }
        Ok(out)
    }

    fn parse_media_query(&mut self) -> Result<MediaQuery, Error> {
        let mut modifier = None;
        self.skip_ws();
        if let Token::Ident(n) = self.cur.clone() {
            if n == "not" {
                self.bump();
                self.skip_ws();
                let inner = self.parse_media_query_in_parens()?;
                return Ok(MediaQuery::Not(Box::new(inner)));
            }
            if n == "only" {
                modifier = Some(n);
                self.bump();
                self.skip_ws();
            }
        }
        let mut left = self.parse_media_query_in_parens()?;
        loop {
            self.skip_ws();
            let and = match self.cur.clone() {
                Token::Ident(n) if n == "and" => {
                    self.bump();
                    true
                }
                Token::Ident(n) if n == "or" => {
                    self.bump();
                    false
                }
                _ => break,
            };
            self.skip_ws();
            let right = self.parse_media_query_in_parens()?;
            left = MediaQuery::Operation(Box::new(left), and, Box::new(right));
        }
        if let Some(m) = modifier {
            if let MediaQuery::Ident {
                media_type,
                ..
            } = &left
            {
                return Ok(MediaQuery::Ident {
                    modifier: Some(m),
                    media_type: media_type.clone(),
                });
            }
        }
        Ok(left)
    }

    fn parse_media_query_in_parens(&mut self) -> Result<MediaQuery, Error> {
        self.skip_ws();
        if self.cur == Token::OpenParenthesis {
            self.bump();
            self.skip_ws();
            // media feature
            let name = match self.cur.clone() {
                Token::Ident(n) => {
                    self.bump();
                    n
                }
                _ => {
                    // e.g. `(width)`
                    self.skip_ws();
                    if self.cur == Token::CloseParenthesis {
                        self.bump();
                    }
                    return Ok(MediaQuery::Feature {
                        name: String::new(),
                        value: None,
                        op: None,
                        is_range: false,
                    });
                }
            };
            self.skip_ws();
            // possible range syntax: `(value op name)` or `(name op value op value)`
            let mut op = None;
            let mut value: Option<String> = None;
            match self.cur.clone() {
                Token::Colon => {
                    self.bump();
                    self.skip_ws();
                    let v = self.parse_media_value();
                    // old range syntax: min-width -> width >= value
                    let (n, o) = modernize_feature(&name, &v);
                    return Ok(MediaQuery::Feature {
                        name: n,
                        value: Some(v),
                        op: o,
                        is_range: false,
                    });
                }
                Token::IncludeMatch
                | Token::DashMatch
                | Token::PrefixMatch
                | Token::SuffixMatch
                | Token::SubstringMatch => {
                    let t = self.text();
                    self.bump();
                    self.skip_ws();
                    let v = self.parse_media_value();
                    return Ok(MediaQuery::Feature {
                        name,
                        value: Some(v),
                        op: None,
                        is_range: false,
                    });
                }
                Token::Delim(c) if c == '<' || c == '>' || c == '=' => {
                    let mut o = c;
                    self.bump();
                    if let Token::Delim(c2) = self.cur.clone() {
                        if c2 == '=' {
                            self.bump();
                            o = match o {
                                '<' => '=',
                                '>' => '=',
                                _ => o,
                            };
                            // build the two-char operator
                        }
                    }
                    self.skip_ws();
                    let v = self.parse_media_value();
                    let _ = o;
                    return Ok(MediaQuery::Feature {
                        name,
                        value: Some(v),
                        op: Some(MediaQueryOp::Eq),
                        is_range: false,
                    });
                }
                _ => {}
            }
            let _ = (&op, &value);
            self.skip_ws();
            if self.cur == Token::CloseParenthesis {
                self.bump();
            }
            return Ok(MediaQuery::Feature {
                name,
                value,
                op,
                is_range: false,
            });
        }
        // A media type
        let t = match self.cur.clone() {
            Token::Ident(n) => {
                self.bump();
                n
            }
            _ => String::new(),
        };
        Ok(MediaQuery::Ident {
            modifier: None,
            media_type: t,
        })
    }

    fn parse_media_value(&mut self) -> String {
        let mut out = String::new();
        loop {
            match self.cur.clone() {
                Token::EOF | Token::CloseParenthesis | Token::Comma => break,
                Token::WhiteSpace => {
                    self.bump();
                    if !out.is_empty() {
                        // stop at whitespace unless part of the value
                        break;
                    }
                }
                Token::Delim(c) if c == '<' || c == '>' => {
                    // range syntax: `value < name < value`
                    let _ = c;
                    break;
                }
                _ => {
                    out.push_str(&self.text());
                    self.bump();
                }
            }
        }
        out
    }

    // ---------------------------------------------------------------- blocks

    fn parse_declaration_block(&mut self) -> Result<DeclarationBlock, Error> {
        let mut block = DeclarationBlock::default();
        loop {
            self.skip_ws();
            match self.cur.clone() {
                Token::EOF | Token::CloseCurlyBracket => break,
                Token::Semicolon => {
                    self.bump();
                }
                Token::AtKeyword(name) => {
                    let name = name.to_string();
                    self.bump();
                    match self.parse_at_rule(&name)? {
                        Some(Rule::Import { .. }) | Some(Rule::Charset(_)) => {
                            return Err(self.err(ErrorKind::UnexpectedImportRule));
                        }
                        Some(r) => block.rules.push(r),
                        None => {}
                    }
                }
                _ => {
                    // Could be a declaration or a nested rule.
                    let d = self.parse_declaration_or_nested(&mut block)?;
                    let _ = d;
                }
            }
        }
        if self.cur == Token::CloseCurlyBracket {
            self.bump();
        }
        Ok(block)
    }

    /// Parse either a declaration or a nested rule.
    fn parse_declaration_or_nested(&mut self, block: &mut DeclarationBlock) -> Result<(), Error> {
        // Try to parse a declaration first.
        let save = self.save();
        match self.parse_declaration() {
            Ok(Some(d)) => {
                block.declarations.push(d);
                return Ok(());
            }
            Ok(None) => {}
            Err(_) => {
                self.restore(save);
            }
        }
        // Otherwise it's a nested rule.
        let selectors = self.parse_nested_selectors()?;
        self.skip_ws();
        if self.cur != Token::OpenCurlyBracket {
            return Err(self.err(ErrorKind::EndOfInput));
        }
        self.bump();
        let inner = self.parse_declaration_block()?;
        block.rules.push(Rule::Nesting { selectors, block: inner });
        Ok(())
    }

    fn parse_nested_selectors(&mut self) -> Result<Vec<Selector>, Error> {
        let mut out = Vec::new();
        let mut cur: Vec<SelectorPart> = Vec::new();
        let mut depth = 0usize;
        loop {
            match self.cur.clone() {
                Token::EOF => {
                    return Err(Error::new(
                        ErrorKind::EndOfInput,
                        &self.filename,
                        self.src,
                        self.cur_start,
                    ))
                }
                Token::OpenCurlyBracket if depth == 0 => break,
                Token::OpenSquareBracket | Token::OpenParenthesis => {
                    depth += 1;
                    cur.push(SelectorPart::Text(self.text()));
                    self.bump();
                }
                Token::CloseSquareBracket | Token::CloseParenthesis => {
                    depth -= 1;
                    cur.push(SelectorPart::Text(self.text()));
                    self.bump();
                }
                Token::Comma if depth == 0 => {
                    self.bump();
                    out.push(Selector {
                        parts: std::mem::take(&mut cur),
                    });
                }
                Token::WhiteSpace => {
                    let t = self.text();
                    self.bump();
                    if !cur.is_empty() {
                        cur.push(SelectorPart::WhiteSpace(t));
                    }
                }
                _ => {
                    let t = self.text();
                    self.bump();
                    cur.push(SelectorPart::Text(t));
                }
            }
        }
        while matches!(cur.last(), Some(SelectorPart::WhiteSpace(_))) {
            cur.pop();
        }
        out.push(Selector { parts: cur });
        Ok(out)
    }

    /// Parse a single declaration (`ident: value[!important]`).
    fn parse_declaration(&mut self) -> Result<Option<Declaration>, Error> {
        let property = match self.cur.clone() {
            Token::Ident(name) => {
                self.bump();
                name.to_string()
            }
            Token::Delim('-') => {
                // vendor prefix
                self.bump();
                let prefix = match self.cur.clone() {
                    Token::Ident(p) => {
                        self.bump();
                        p
                    }
                    _ => return Err(self.err(ErrorKind::InvalidDeclaration)),
                };
                match self.cur.clone() {
                    Token::Ident(name) => {
                        self.bump();
                        let p: &'static str = match prefix.as_str() {
                            "webkit" => "webkit",
                            "moz" => "moz",
                            "ms" => "ms",
                            "o" => "o",
                            _ => "webkit",
                        };
                        let _ = p;
                        return Ok(Some(Declaration {
                            property: format!("-{}-{}", prefix, name),
                            value: self.parse_property_value(&name)?,
                            important: self.parse_important(),
                            prefix: None,
                        }));
                    }
                    _ => return Err(self.err(ErrorKind::InvalidDeclaration)),
                }
            }
            _ => return Err(self.err(ErrorKind::InvalidDeclaration)),
        };
        self.skip_ws();
        if self.cur != Token::Colon {
            return Err(self.err(ErrorKind::EndOfInput));
        }
        self.bump();
        let value = self.parse_property_value(&property)?;
        let important = self.parse_important();
        self.consume_semicolon();
        Ok(Some(Declaration {
            property,
            value,
            important,
            prefix: None,
        }))
    }

    fn parse_important(&mut self) -> bool {
        let save_pos = self.tok.position();
        self.skip_ws();
        if self.cur == Token::Delim('!') {
            self.bump();
            self.skip_ws();
            if let Token::Ident(name) = self.cur.clone() {
                if name.eq_ignore_ascii_case("important") {
                    self.bump();
                    return true;
                }
            }
        }
        self.restore((save_pos, self.cur.clone(), self.cur_start, self.cur_end));
        false
    }

    fn consume_semicolon(&mut self) {
        self.skip_ws();
        if self.cur == Token::Semicolon {
            self.bump();
        }
    }

    /// Parse a property value, using typed parsing for known properties and a
    /// raw token list otherwise.
    fn parse_property_value(&mut self, property: &str) -> Result<Value, Error> {
        if property.starts_with("--") {
            let raw = self.parse_raw_tokens(None);
            return Ok(Value::Raw(raw));
        }
        match crate::properties::property_kind(property) {
            crate::properties::PropertyKind::Unknown => {
                let raw = self.parse_raw_tokens(None);
                Ok(Value::Raw(raw))
            }
            _ => self.parse_typed_value(property),
        }
    }

    /// Parse a value into a typed Value tree.
    fn parse_typed_value(&mut self, _property: &str) -> Result<Value, Error> {
        let items = self.parse_component_list()?;
        if items.is_empty() {
            return Ok(Value::Empty);
        }
        if items.len() == 1 {
            return Ok(items.into_iter().next().unwrap());
        }
        Ok(Value::CommaList(items))
    }

    fn parse_component_list(&mut self) -> Result<Vec<Value>, Error> {
        let mut out = Vec::new();
        loop {
            let comps = self.parse_space_list()?;
            if !comps.is_empty() {
                out.push(if comps.len() == 1 {
                    comps.into_iter().next().unwrap()
                } else {
                    Value::List(comps)
                });
            }
            self.skip_ws();
            if self.cur == Token::Comma {
                self.bump();
                continue;
            }
            break;
        }
        Ok(out)
    }

    fn parse_space_list(&mut self) -> Result<Vec<Value>, Error> {
        let mut out = Vec::new();
        loop {
            self.skip_ws();
            match self.cur.clone() {
                Token::EOF | Token::Semicolon | Token::Comma | Token::CloseCurlyBracket => break,
                _ => {
                    let v = self.parse_component()?;
                    out.push(v);
                }
            }
        }
        Ok(out)
    }

    fn parse_component(&mut self) -> Result<Value, Error> {
        match self.cur.clone() {
            Token::Ident(name) => {
                self.bump();
                if is_color_ident(&name) {
                    if let Some((r, g, b)) = named_color(&name) {
                        return Ok(Value::Color(Color::Rgba(r, g, b, 1.0)));
                    }
                }
                if name == "currentcolor" {
                    return Ok(Value::Color(Color::CurrentColor));
                }
                if name == "transparent" {
                    return Ok(Value::Color(Color::Transparent));
                }
                Ok(Value::Ident(name))
            }
            Token::Number {
                value,
                int_value,
                ..
            } => {
                self.bump();
                Ok(Value::Number(Number {
                    value,
                    int_value,
                    unit: None,
                }))
            }
            Token::Percentage {
                value,
                int_value,
                ..
            } => {
                self.bump();
                Ok(Value::Number(Number {
                    value,
                    int_value,
                    unit: Some("%".to_string()),
                }))
            }
            Token::Dimension {
                value,
                int_value,
                unit,
                ..
            } => {
                self.bump();
                Ok(Value::Number(Number {
                    value,
                    int_value,
                    unit: Some(unit.to_string()),
                }))
            }
            Token::Str(s) => {
                self.bump();
                Ok(Value::Str(s))
            }
            Token::Hash { value, .. } => {
                self.bump();
                match parse_hex(value) {
                    Some((r, g, b, a)) => Ok(Value::Color(Color::Rgba(r, g, b, a))),
                    None => Ok(Value::Raw(vec![format!("#{}", value)])),
                }
            }
            Token::UnquotedUrl(_) => {
                let start = self.cur_start;
                self.bump();
                let text = &self.src[start..self.cur_end];
                let inner = text
                    .trim_start_matches("url(")
                    .trim_end_matches(')')
                    .trim();
                Ok(Value::Url(Some(inner.to_string())))
            }
            Token::Function(name) => {
                let name = name.to_string();
                self.bump();
                self.parse_function(&name)
            }
            Token::OpenParenthesis => {
                self.bump();
                let inner = self.parse_space_list()?;
                let res = if inner.len() == 1 {
                    inner.into_iter().next().unwrap()
                } else if inner.is_empty() {
                    Value::Empty
                } else {
                    Value::List(inner)
                };
                if self.cur == Token::CloseParenthesis {
                    self.bump();
                }
                Ok(res)
            }
            _ => {
                let t = self.text();
                self.bump();
                Ok(Value::Raw(vec![t]))
            }
        }
    }

    fn parse_function(&mut self, name: &str) -> Result<Value, Error> {
        match name {
            "var" => {
                self.skip_ws();
                let custom = match self.cur.clone() {
                    Token::Ident(n) if n.starts_with("--") => {
                        self.bump();
                        n
                    }
                    _ => return Err(self.err(ErrorKind::InvalidValue)),
                };
                let mut fallback = None;
                self.skip_ws();
                if self.cur == Token::Comma {
                    self.bump();
                    let items = self.parse_component_list()?;
                    fallback = Some(items);
                }
                if self.cur == Token::CloseParenthesis {
                    self.bump();
                }
                Ok(Value::Var { name: custom, fallback })
            }
            "rgb" | "rgba" | "hsl" | "hsla" | "hwb" | "color" | "color-mix" => {
                self.skip_ws();
                let items = self.parse_component_list()?;
                if self.cur == Token::CloseParenthesis {
                    self.bump();
                }
                match parse_color_function(name, &items) {
                    Some(c) => Ok(Value::Color(c)),
                    None => {
                        // not a valid color: keep raw
                        let mut v = vec![format!("{}(", name)];
                        v.extend(raw_of(&Value::CommaList(items)));
                        v.push(")".to_string());
                        Ok(Value::Raw(v))
                    }
                }
            }
            _ => {
                self.skip_ws();
                let items = self.parse_component_list()?;
                if self.cur == Token::CloseParenthesis {
                    self.bump();
                }
                let mut v = vec![format!("{}(", name)];
                v.extend(raw_of(&Value::CommaList(items)));
                v.push(")".to_string());
                Ok(Value::Raw(v))
            }
        }
    }

    /// Parse tokens into raw text, stopping at the given tokens (or `;`/`}`/EOF).
    fn parse_raw_tokens(&mut self, _stop: Option<&[Token<'a>]>) -> Vec<String> {
        let mut out: Vec<String> = Vec::new();
        let mut depth = 0usize;
        loop {
            match self.cur.clone() {
                Token::EOF => break,
                Token::Semicolon if depth == 0 => break,
                Token::CloseCurlyBracket if depth == 0 => break,
                Token::OpenCurlyBracket
                | Token::OpenParenthesis
                | Token::OpenSquareBracket
                | Token::Function(_) => {
                    if matches!(self.cur, Token::Function(_)) {
                        // function: keep as raw, including its arguments
                        out.push(self.text());
                        self.bump();
                        depth += 1;
                        continue;
                    }
                    depth += 1;
                    out.push(self.text());
                    self.bump();
                }
                Token::CloseCurlyBracket | Token::CloseParenthesis | Token::CloseSquareBracket => {
                    if depth == 0 {
                        break;
                    }
                    depth -= 1;
                    out.push(self.text());
                    self.bump();
                }
                Token::WhiteSpace => {
                    let t = self.text();
                    self.bump();
                    out.push(t);
                }
                Token::Comment(c) => {
                    let t = format!("/*{}*/", c);
                    self.bump();
                    out.push(t);
                }
                Token::Str(s) => {
                    let mut t = String::new();
                    serialize_string(&s, &mut t);
                    self.bump();
                    out.push(t);
                }
                _ => {
                    let t = self.text();
                    self.bump();
                    out.push(t);
                }
            }
        }
        out
    }
}

fn raw_of(v: &Value) -> Vec<String> {
    match v {
        Value::Raw(r) => r.clone(),
        Value::Empty => Vec::new(),
        Value::List(items) => {
            let mut out = Vec::new();
            for (i, it) in items.iter().enumerate() {
                if i > 0 {
                    out.push(" ".to_string());
                }
                out.extend(raw_of(it));
            }
            out
        }
        Value::CommaList(items) => {
            let mut out = Vec::new();
            for (i, it) in items.iter().enumerate() {
                if i > 0 {
                    out.push(",".to_string());
                }
                out.extend(raw_of(it));
            }
            out
        }
        _ => vec![serialize_value_to_string(v, false)],
    }
}

pub fn serialize_value_to_string(v: &Value, minify: bool) -> String {
    let mut p = crate::printer::Printer::new(minify);
    p.value(v);
    p.out
}

fn is_ident_string(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    let mut chars = s.chars();
    let first = chars.next().unwrap();
    if !(first.is_alphabetic() || first == '_' || first == '-' || first == '\\' || first >= '\u{80}')
    {
        return false;
    }
    if first == '-' {
        // A leading hyphen must not be followed by a digit.
        if let Some(c) = chars.next() {
            if c.is_ascii_digit() {
                return false;
            }
        }
    }
    for c in chars {
        if !(c.is_alphanumeric() || c == '_' || c == '-' || c == '\\' || c >= '\u{80}') {
            return false;
        }
    }
    true
}

/// Convert old-style media feature range syntax (`min-width: 100px`) to the
/// modern syntax (`width >= 100px`).
fn modernize_feature(name: &str, value: &str) -> (String, Option<MediaQueryOp>) {
    if let Some(n) = name.strip_prefix("min-") {
        let n = match n {
            "width" => "width",
            "height" => "height",
            "block-size" => "block-size",
            "inline-size" => "inline-size",
            "aspect-ratio" => "aspect-ratio",
            "color-gamut" => "color-gamut",
            _ => name,
        };
        if n != name {
            return (n.to_string(), Some(MediaQueryOp::Ge));
        }
    } else if let Some(n) = name.strip_prefix("max-") {
        let n = match n {
            "width" => "width",
            "height" => "height",
            "block-size" => "block-size",
            "inline-size" => "inline-size",
            "aspect-ratio" => "aspect-ratio",
            "color-gamut" => "color-gamut",
            _ => name,
        };
        if n != name {
            return (n.to_string(), Some(MediaQueryOp::Le));
        }
    }
    (name.to_string(), None)
}

/// Normalize a container query condition (e.g. `(min-width: 100px)` to
/// `(width >= 100px)`).
pub fn normalize_container_condition(s: &str) -> String {
    let s = s.trim();
    // Handle simple `(min-width: X)` / `(max-width: X)` forms.
    let inner = s.trim_start_matches('(').trim_end_matches(')');
    for (prefix, op) in [("min-", ">="), ("max-", "<=")] {
        if let Some(rest) = inner.strip_prefix(prefix) {
            if let Some((name, value)) = rest.split_once(':') {
                let name = name.trim();
                let value = value.trim();
                if matches!(name, "width" | "height" | "inline-size" | "block-size") {
                    return format!("({} {} {})", name, op, value);
                }
            }
        }
    }
    s.to_string()
}
