//! Property tables: classification, ordering and shorthand information.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PropertyKind {
    Unknown,
    Typed,
    Color,
}

/// Whether a property has a typed value grammar that we parse.
pub fn property_kind(_property: &str) -> PropertyKind {
    PropertyKind::Typed
}

/// The vendor prefixes recognized by lightningcss.
pub const PREFIXES: [&str; 4] = ["webkit", "moz", "ms", "o"];

/// Properties that are vendor-prefixed variants of unprefixed ones.
pub fn unprefixed(property: &str) -> Option<&'static str> {
    for p in PREFIXES {
        let prefix = format!("-{}-", p);
        if let Some(rest) = property.strip_prefix(&prefix) {
            return Some(rest);
        }
    }
    None
}

// ---------------------------------------------------------------------------
// Declaration ordering
// ---------------------------------------------------------------------------

/// The order groups used when re-ordering declarations for minification.
/// Each entry is (family, kind, slot) where kind 0 = physical/shorthand and
/// kind 1 = logical. Properties in the same family but with different kinds
/// compare equal, mirroring lightningcss's behaviour.
pub struct OrderKey {
    pub family: u16,
    pub kind: u8,
    pub slot: u16,
}

pub const KIND_OTHER: u8 = 0;
pub const KIND_LOGICAL: u8 = 1;

pub fn order_key(property: &str) -> OrderKey {
    let (f, k, s) = lookup(property);
    OrderKey {
        family: f,
        kind: k,
        slot: s,
    }
}

fn f(name: &str) -> u16 {
    // family ids, assigned in the order they are used below
    match name {
        "custom" => 0,
        "color" => 1,
        "background" => 2,
        "border" => 3,
        "outline" => 4,
        "width" => 5,
        "margin" => 6,
        "padding" => 7,
        "font" => 8,
        "line" => 9,
        "display" => 10,
        "position" => 11,
        "inset" => 12,
        "box" => 13,
        "other" => 14,
        _ => 14,
    }
}

fn lookup(property: &str) -> (u16, u8, u16) {
    use crate::props_data::ORDER;
    match ORDER.iter().find(|(n, _, _, _)| *n == property) {
        Some((_, fa, k, s)) => (*fa, *k, *s),
        None => (0, 0, 0),
    }
}

/// Compare two order keys the way lightningcss does.
pub fn cmp_order(a: &OrderKey, b: &OrderKey) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    if a.family != b.family {
        return a.family.cmp(&b.family);
    }
    if a.kind != b.kind {
        return Ordering::Equal;
    }
    a.slot.cmp(&b.slot)
}
RSEOF
echo ok"}

