        Error {
            kind,
            loc: None,
        }
    }

    /// The message shown by `--error-recovery`.
    pub fn to_message(&self) -> String {
        let base = match &self.kind {
            ErrorKind::EndOfInput => "Unexpected end of input".to_string(),
            ErrorKind::UnexpectedImportRule => {
                "Unexpected @import rule".to_string()
