            ErrorKind::SelectorError(s) => s.clone(),
            ErrorKind::UnknownAtRule(n) => format!("Unknown at rule: @{}", n),
            ErrorKind::CustomMediaNotEnabled => {
                "Cannot use custom media queries. Pass custom_media: true.".to_string()
            }
            ErrorKind::KeyframesInvalid => "Invalid keyframes".to_string(),
            ErrorKind::SpecifierError => "Invalid specifier".to_string(),
            ErrorKind::ResolverError(e) => format!("Error resolving file {}", e),
            ErrorKind::InvalidValue => "Invalid value".to_string(),
            ErrorKind::UnexpectedDeclaration => "Unexpected declaration".to_string(),
            ErrorKind::NotABlock => "Not a block".to_string(),
        };
        match &self.loc {
            Some(l) => format!("{} at {}:{}:{}", base, l.filename, l.line, l.column),
            None => base,
        }
    }
}

/// Compute a 0-based line and 1-based column for a byte offset.
pub fn line_col(source: &str, pos: usize) -> (usize, usize) {
    let pos = pos.min(source.len());
    let mut line = 0;
    let mut col = 0;
    for c in source[..pos].chars() {
        if c == '\n' {
            line += 1;
            col = 0;
        } else {
            col += 1;
        }
    }
    (line, col + 1)
}
