            while j < chars.len() {
                let c = chars[j];
                match c {
                    'h' => return ParseResult::Printed(help_text(bin)),
                    'V' => return ParseResult::Printed(format!("{}\n", VERSION)),
                    'm' => opts.minify = true,
                    'd' | 'o' | 't' => {
                        // value: the rest of this arg, or the next one
                        let rest: String = chars[j + 1..].iter().collect();
                        let value = if !rest.is_empty() {
                            rest.trim_start_matches('=').to_string()
                        } else {
                            i += 1;
                            consumed_next = true;
                            match args.get(i) {
                                Some(v) => v.clone(),
                                None => {
                                    let name = match c {
                                        'o' => "--output-file <OUTPUT_FILE>",
                                        'd' => "--output-dir <OUTPUT_DIR>",
                                        _ => "--targets <TARGETS>",
                                    };
                                    return ParseResult::Err(
                                        format!(
                                            "error: The argument '{}' requires a value but none was supplied\n\nFor more information try --help\n",
                                            name
                                        ),
                                        2,
                                    )
                                }
                            }
                        };
                        match c {
                            'o' => opts.output_file = Some(value),
                            'd' => opts.output_dir = Some(value),
                            _ => opts.targets = Some(value),
                        }
                        j = chars.len();
                        break;
                    }
                    _ => {
                        return ParseResult::Err(
                            format!(
                                "error: Found argument '-{}' which wasn't expected, or isn't valid in this context\n\n\tIf you tried to supply `-{}` as a value rather than a flag, use `-- -{}`\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
                                c, c, c, usage_line(bin)
                            ),
                            2,
                        )
                    }
                }
                j += 1;
            }
            let _ = consumed_next;
            i += 1;
            continue;
        }
        opts.inputs.push(a.clone());
        i += 1;
    }
    ParseResult::Ok(opts)
}

fn display_arg(long: &str) -> String {
    match long {
        "--css-modules" => "--css-modules [<CSS_MODULES>]".to_string(),
        "--css-modules-pattern" => "--css-modules-pattern <CSS_MODULES_PATTERN>".to_string(),
        "--output-dir" => "--output-dir <OUTPUT_DIR>".to_string(),
        "--output-file" => "--output-file <OUTPUT_FILE>".to_string(),
        "--targets" => "--targets <TARGETS>".to_string(),
        _ => long.to_string(),
    }
}
