        opts.error_recovery,
    );
    let mut sheet = p.parse_stylesheet().unwrap();
    if let Some(t) = &opts.targets {
        let targets = crate::minify::parse_targets(t);
        crate::minify::apply_targets(&mut sheet, &targets);
    }
    crate::minify::minify(&mut sheet, opts.minify);
    let mut printer = printer::Printer::new(opts.minify);
    printer.stylesheet(&sheet);
    let code = printer.out;
    let map = if opts.sourcemap {
        Some(sourcemap::generate(filename, source, &code, source_index))
    } else {
        None
    };
    (code, map)
}

fn main() {
    let argv: Vec<String> = std::env::args().collect();
    let bin = argv
        .first()
        .map(|s| {
            Path::new(s)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| s.clone())
        })
        .unwrap_or_else(|| "lightningcss".to_string());
    let args: Vec<String> = argv.iter().skip(1).cloned().collect();
    let opts = match cli::parse_args(&args, &bin) {
        cli::ParseResult::Printed(s) => {
            print!("{}", s);
            std::process::exit(0);
        }
        cli::ParseResult::Err(msg, code) => {
            eprint!("{}", msg);
            std::process::exit(code);
        }
        cli::ParseResult::Ok(o) => o,
    };

    if opts.inputs.len() > 1 && opts.output_file.is_some() {
        eprintln!(
            "Cannot use the --output-file option with multiple inputs. Use --output-dir instead."
        );
        std::process::exit(1);
    }
    if opts.inputs.len() > 1 && opts.output_file.is_none() && opts.output_dir.is_none() {
        eprintln!("Cannot output to stdout with multiple inputs. Use --output-dir instead.");
        std::process::exit(1);
    }

    let mut outputs: Vec<(String, String, Option<sourcemap::SourceMap>, String)> = Vec::new();
    if opts.inputs.is_empty() {
        let mut buf = String::new();
        std::io::stdin().read_to_string(&mut buf).unwrap();
        let filename = format!("stdin-{}", std::process::id());
        let (code, map) = run_single(&filename, &buf, &opts, 0);
        outputs.push((filename, code, map, buf));
    } else {
        for (i, input) in opts.inputs.iter().enumerate() {
            let path = Path::new(input);
            let canonical = std::fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
            let filename = relative_to_cwd(&canonical);
            let source = std::fs::read_to_string(path).unwrap();
            let (code, map) = run_single(&filename, &source, &opts, i);
            let name = path
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| input.clone());
            outputs.push((name, code, map, source));
        }
    }

    // Write the outputs.
    if let Some(dir) = &opts.output_dir {
        std::fs::create_dir_all(dir).unwrap();
        for (name, code, map, _src) in outputs {
            let mut out_path = Path::new(dir).join(&name);
            if let Some(pattern) = &opts.css_modules_pattern {
                let _ = pattern;
            }
            let data = match &map {
                Some(m) => format!("{}/*# sourceMappingURL={} */\n", code, {
                    let p = format!("{}.map", out_path.to_string_lossy());
                    p
                }),
                None => code.clone(),
            };
            std::fs::write(&out_path, data).unwrap();
            out_path = Path::new(dir).join(&name);
            if let Some(m) = map {
                let mp = format!("{}.map", out_path.to_string_lossy());
                std::fs::write(mp, m.to_json()).unwrap();
            }
        }
    } else if let Some(out) = &opts.output_file {
        let code = &outputs[0].1;
        let data = match &outputs[0].2 {
            Some(m) => {
                let mp = format!("{}.map", out);
                format!("{}/*# sourceMappingURL={} */\n", code, mp)
            }
            None => code.clone(),
        };
        std::fs::write(out, data).unwrap();
        if let Some(m) = &outputs[0].2 {
            std::fs::write(format!("{}.map", out), m.to_json()).unwrap();
        }
    } else if let Some(css_modules) = &opts.css_modules {
        let (code, name) = &outputs[0];
        let exports = crate::minify::css_modules_exports(name);
        let code_str = code.clone();
        let obj = serde_like_json(&exports, &code_str);
        if let Some(file) = css_modules {
            std::fs::write(file, obj).unwrap();
            print!("{}", code);
        } else {
            print!("{}", obj);
        }
    } else {
        for (_name, code, _m, _s) in &outputs {
            print!("{}", code);
        }
    }
}

fn relative_to_cwd(path: &Path) -> String {
    let cwd = std::env::current_dir().unwrap_or_else(|_| Path::new(".").to_path_buf());
    match path.strip_prefix(&cwd) {
        Ok(p) => p.to_string_lossy().to_string(),
        Err(_) => {
            // Try to build a relative path
            let cwd_comps: Vec<_> = cwd.components().collect();
            let p_comps: Vec<_> = path.components().collect();
            let mut common = 0;
            while common < cwd_comps.len()
                && common < p_comps.len()
                && cwd_comps[common] == p_comps[common]
            {
                common += 1;
            }
            let mut parts: Vec<String> = Vec::new();
            for _ in common..cwd_comps.len() {
                parts.push("..".to_string());
            }
            for c in &p_comps[common..] {
                parts.push(c.as_os_str().to_string_lossy().to_string());
            }
            parts.join("/")
        }
    }
}

/// Very small JSON serializer for the CSS modules output.
fn serde_like_json(exports: &std::collections::BTreeMap<String, String>, code: &str) -> String {
    let mut s = String::from("{");
    s.push_str("\"code\":");
    s.push_str(&json_string(code));
    s.push_str(",\"exports\":{");
    let mut first = true;
    for (k, v) in exports {
        if !first {
            s.push(',');
        }
        first = false;
        s.push_str(&json_string(k));
        s.push(':');
        s.push_str(&json_string(v));
    }
    s.push_str("}}");
    s
}

pub fn json_string(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}
