pub fn encode_vlq(out: &mut String, mut value: i32) {
    let mut vlq = if value >= 0 { value << 1 } else { ((-value) << 1) | 1 };
    loop {
        let mut digit = vlq & 0b11111;
        vlq >>= 5;
        if vlq > 0 {
            digit |= 0b100000;
        }
        out.push(B64[digit as usize] as char);
        if vlq == 0 {
            break;
        }
    }
}

/// Generate a trivial source map: map the whole output to the start of the source.
pub fn generate(filename: &str, source: &str, _code: &str, _index: usize) -> SourceMap {
    let mut mappings = String::new();
    // One segment: column 0 -> source 0, line 0, column 0.
    encode_vlq(&mut mappings, 0);
    encode_vlq(&mut mappings, 0);
    encode_vlq(&mut mappings, 0);
    encode_vlq(&mut mappings, 0);
    mappings.push(';');
    SourceMap {
        sources: vec![filename.to_string()],
        sources_content: vec![source.to_string()],
        mappings,
    }
}
