fn parse_version(s: &str) -> u32 {
    let parts: Vec<&str> = s.split('.').collect();
    let mut v = 0u32;
    for (i, p) in parts.iter().take(4).enumerate() {
        let n: u32 = p.parse().unwrap_or(0);
        v |= n << (8 * (3 - i));
    }
