// ---------------------------------------------------------------------------
// Declaration ordering
// ---------------------------------------------------------------------------

fn decl_rank(d: &Declaration) -> Option<crate::properties::OrderKey> {
    if !crate::minify_values::is_parsed(&d.value) {
        return None;
    }
    Some(crate::properties::order_key(&d.property))
}

fn cmp_declarations(a: &Declaration, b: &Declaration) -> Ordering {
    match (decl_rank(a), decl_rank(b)) {
        (None, _) | (_, None) => Ordering::Equal,
        (Some(x), Some(y)) => crate::properties::cmp_order(&x, &y),
    }
}

/// Reorder declarations using an insertion sort with the (partially ordered)
/// declaration ranks.
pub fn reorder_declarations(decls: &mut Vec<Declaration>) {
    let n = decls.len();
    if n < 2 {
        return;
    }
    for i in 1..n {
        let mut j = i;
        while j > 0 && cmp_declarations(&decls[j - 1], &decls[j]) == Ordering::Greater {
            decls.swap(j - 1, j);
            j -= 1;
        }
    }
}

// ---------------------------------------------------------------------------
// Rule merging
// ---------------------------------------------------------------------------

fn declarations_equal(a: &[Declaration], b: &[Declaration]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    a.iter().zip(b.iter()).all(|(x, y)| {
        x.property == y.property && x.value == y.value && x.important == y.important
    })
}

pub fn minify(sheet: &mut Stylesheet, _minify: bool) {
    minify_rules(&mut sheet.rules);
}

fn minify_rules(rules: &mut Vec<Rule>) {
    // Recurse into nested rules first.
    for rule in rules.iter_mut() {
        match rule {
            Rule::Media { rules, .. } | Rule::Supports { rules, .. } => minify_rules(rules),
            Rule::Layer { rules, .. } | Rule::Container { rules, .. } => minify_rules(rules),
            Rule::Style { block, .. } | Rule::Nesting { block, .. } => {
                crate::minify_values::minify_declarations(&mut block.declarations);
                for r in block.rules.iter_mut() {
                    match r {
                        Rule::Media { rules, .. } | Rule::Supports { rules, .. } => {
                            minify_rules(rules)
                        }
                        _ => {}
                    }
                }
            }
            _ => {}
        }
    }
    // Reorder declarations in style blocks.
    for rule in rules.iter_mut() {
        if let Rule::Style { block, .. } = rule {
            reorder_declarations(&mut block.declarations);
        }
        if let Rule::Nesting { block, .. } = rule {
            reorder_declarations(&mut block.declarations);
        }
    }
    // Merge adjacent rules with identical declarations.
    let mut merged: Vec<Rule> = Vec::new();
    for rule in rules.drain(..) {
        if let Some(last) = merged.last_mut() {
            if let (Rule::Style { selectors: ls, block: lb }, Rule::Style { selectors: rs, block: rb }) =
                (last, &rule)
            {
                if lb.rules.is_empty()
                    && rb.rules.is_empty()
                    && declarations_equal(&lb.declarations, &rb.declarations)
                    && !lb.declarations.is_empty()
                {
                    ls.extend(rs.iter().cloned());
                    continue;
                }
            }
        }
        merged.push(rule);
    }
    *rules = merged;
}

