//! Value level minification.

use crate::ast::*;
use crate::values::*;

/// Whether a value was fully parsed (not a raw token list).
pub fn is_parsed(v: &Value) -> bool {
    !matches!(v, Value::Raw(_) | Value::Empty)
}

pub fn minify_declarations(decls: &mut [Declaration]) {
    for d in decls.iter_mut() {
        minify_value(d);
    }
}

fn minify_value(d: &mut Declaration) {
    match &mut d.value {
        Value::Raw(_) | Value::Empty => {}
        Value::Number(n) => {
            n.unit = shorten_unit(&n.unit);
        }
        Value::Color(c) => {
            convert_color(c);
        }
        Value::List(items) | Value::CommaList(items) => {
            for it in items.iter_mut() {
                minify_component(it);
            }
        }
        _ => {}
    }
}

fn minify_component(v: &mut Value) {
    match v {
        Value::Number(n) => {
            n.unit = shorten_unit(&n.unit);
        }
        Value::Color(c) => convert_color(c),
        Value::List(items) | Value::CommaList(items) => {
            for it in items.iter_mut() {
                minify_component(it);
            }
        }
        _ => {}
    }
}

pub fn shorten_unit(unit: &Option<String>) -> Option<String> {
    match unit.as_deref() {
        Some("px") => None,
        Some("ms") => Some("ms".to_string()),
        Some("initial") => None,
        _ => unit.clone(),
    }
}

pub fn convert_color(c: &mut Color) {
    match c {
        Color::Hsla(h, s, l, a) => {
            let (r, g, b) = crate::values::hsl_to_rgb(*h, *s / 100.0, *l / 100.0);
            *c = Color::Rgba(r, g, b, *a);
        }
        Color::Mix(m) => {
            convert_color(&mut m.color1);
            convert_color(&mut m.color2);
            // Naive mix in sRGB.
            let (r1, g1, b1) = match m.color1 {
                Color::Rgba(r, g, b, _) => (r as f32, g as f32, b as f32),
                _ => (0.0, 0.0, 0.0),
            };
            let (r2, g2, b2) = match m.color2 {
                Color::Rgba(r, g, b, _) => (r as f32, g as f32, b as f32),
                _ => (0.0, 0.0, 0.0),
            };
            let w1 = m.pct1.unwrap_or(0.5);
            let w2 = 1.0 - w1;
            let mix = |a: f32, b: f32| crate::values::clamp_u8(a * w1 + b * w2);
            *c = Color::Rgba(mix(r1, r2), mix(g1, g2), mix(b1, b2), 1.0);
        }
        _ => {}
    }
}
