//! Parsing of color functions.

use crate::ast::{Color, ColorMix};
use crate::values::{clamp01, clamp_u8, hsl_to_rgb, hwb_to_rgb, parse_number_units};

/// Parse a color function such as rgb(), hsl(), hwb(), color-mix().
pub fn parse_color_function(name: &str, args: &[crate::values::Value]) -> Option<Color> {
    match name {
        "rgb" | "rgba" => parse_rgb(args),
        "hsl" | "hsla" => parse_hsl(args),
        "hwb" => parse_hwb(args),
        "color-mix" => parse_color_mix(args),
        _ => None,
    }
}

fn num(v: &crate::values::Value) -> Option<f32> {
    match v {
        crate::values::Value::Number(n) => Some(n.value),
        _ => None,
    }
}

fn is_pct(v: &crate::values::Value) -> bool {
    matches!(
        v,
        crate::values::Value::Number(crate::values::Number {
            unit: Some(u),
            ..
        })
        if u == "%"
    )
}

fn channel(v: &crate::values::Value) -> Option<f32> {
    // A value in the range 0..=255 or a percentage.
    match v {
        crate::values::Value::Number(n) => match n.unit.as_deref() {
            Some("%") => Some(n.value * 255.0 / 100.0),
            _ => Some(n.value),
        },
        _ => None,
    }
}

fn parse_rgb(args: &[crate::values::Value]) -> Option<Color> {
    if args.is_empty() {
        return None;
    }
    let comps: Vec<&crate::values::Value> = match &args[0] {
        crate::values::Value::List(v) => v.iter().collect(),
        crate::values::Value::CommaList(v) => v.iter().collect(),
        other => vec![other],
    };
    if comps.len() < 3 {
        return None;
    }
    let alpha = comps.get(3).and_then(|v| num(v)).map(clamp01);
    if comps.len() > 4 {
        return None;
    }
    // Check for percentages: if any component is a percentage, all are.
    let any_pct = comps.iter().take(3).any(|v| is_pct(v));
    if any_pct {
        let r = comps[0];
        let g = comps[1];
        let b = comps[2];
        let (r, g, b) = match (r, g, b) {
            (
                crate::values::Value::Number(a),
                crate::values::Value::Number(bb),
                crate::values::Value::Number(c),
            ) => {
                let f = |x: &crate::values::Number| match x.unit.as_deref() {
                    Some("%") => clamp_u8(x.value * 2.55),
                    _ => clamp_u8(x.value),
                };
                (f(a), f(bb), f(c))
            }
            _ => return None,
        };
        return Some(Color::Rgba(r, g, b, alpha.unwrap_or(1.0)));
    }
    let r = clamp_u8(channel(comps[0])?);
    let g = clamp_u8(channel(comps[1])?);
    let b = clamp_u8(channel(comps[2])?);
    Some(Color::Rgba(r, g, b, alpha.unwrap_or(1.0)))
}

fn parse_hsl(args: &[crate::values::Value]) -> Option<Color> {
    if args.is_empty() {
        return None;
    }
    let comps: Vec<&crate::values::Value> = match &args[0] {
        crate::values::Value::List(v) => v.iter().collect(),
        crate::values::Value::CommaList(v) => v.iter().collect(),
        other => vec![other],
    };
    if comps.len() < 3 {
        return None;
    }
    let h = parse_angle(&comps[0])?;
    let s = match comps[1] {
        crate::values::Value::Number(n) => n.value,
        _ => return None,
    };
    let l = match comps[2] {
        crate::values::Value::Number(n) => n.value,
        _ => return None,
    };
    let a = comps.get(3).and_then(|v| num(v)).map(clamp01);
    Some(Color::Hsla(h, s, l, a.unwrap_or(1.0)))
}

fn parse_angle(v: &crate::values::Value) -> Option<f32> {
    match v {
        crate::values::Value::Number(n) => match n.unit.as_deref() {
            Some("deg") => Some(n.value),
            Some("grad") => Some(n.value * 0.9),
            Some("rad") => Some(n.value * 180.0 / std::f32::consts::PI),
            Some("turn") => Some(n.value * 360.0),
            None => Some(n.value),
            _ => None,
        },
        _ => None,
    }
}

fn parse_hwb(args: &[crate::values::Value]) -> Option<Color> {
    if args.is_empty() {
        return None;
    }
    let comps: Vec<&crate::values::Value> = match &args[0] {
        crate::values::Value::List(v) => v.iter().collect(),
        crate::values::Value::CommaList(v) => v.iter().collect(),
        other => vec![other],
    };
    if comps.len() < 3 {
