s=open('src/colors.rs').read()
s=s.replace("crate::values::serialize_value_to_string","crate::parser::serialize_value_to_string")
open('src/colors.rs','w').write(s)
# move serialize_value_to_string to values.rs
s=open('src/parser.rs').read()
s=s.replace("""pub fn serialize_value_to_string(v: &Value, minify: bool) -> String {
    let mut p = crate::printer::Printer::new(minify);
    p.value(v);
    p.out
}""","")
open('src/parser.rs','w').write(s)
s=open('src/values.rs').read()
s += """
pub fn serialize_value_to_string(v: &crate::ast::Value, minify: bool) -> String {
    let mut p = crate::printer::Printer::new(minify);
    p.value(v);
    p.out
}
"""
open('src/values.rs','w').write(s)
PYEOF
timeout 300 cargo build --release --offline 2>&1 | grep -E "^error" -A6 | grep -E "^(error|  +-->|[0-9]+ \|\s+[a-z])" | head -20

