s=s.replace("""/// Expand a mantissa (which may contain a '.') by `exp` positions to plain decimal.
fn decimal_from_sci(mant: &str, exp: usize) -> String {
    let int_len = mant.find('.').unwrap_or(mant.len());
    let digits: String = mant.chars().filter(|c| *c != '.').collect();
    let digits = digits.trim_end_matches('0');
    let digits = if digits.is_empty() { "0" } else { digits };
    if int_len > exp {
        // decimal point inside the digits
        let (a, b) = digits.split_at(int_len);
        format!("{}.{}", a, b)
    } else {
        let mut r = digits.to_string();
        for _ in 0..(exp + 1 - digits.len().max(int_len)) {
            r.push('0');
        }
        r
    }
}""","""/// Expand a mantissa (which may contain a '.') by `exp` positions to plain decimal.
fn decimal_from_sci(mant: &str, exp: usize) -> String {
    let digits: String = mant.chars().filter(|c| *c != '.').collect();
    let digits = digits.trim_end_matches('0');
    let digits = if digits.is_empty() { "0" } else { digits };
    let point = exp + 1;
    if digits.len() > point {
        let (a, b) = digits.split_at(point);
        format!("{}.{}", a, b)
    } else {
        let mut r = digits.to_string();
        for _ in 0..(point - digits.len()) {
            r.push('0');
        }
        r
    }
}""")
open('src/values.rs','w').write(s)

s=open('src/printer.rs').read()
s=s.replace("""    fn declaration_block(&mut self, block: &DeclarationBlock) {
        self.out.push_str(" {");
        self.out.push('\\n');
        if self.minify {
            self.declaration_block_inner(block);
        } else {""","""    fn declaration_block(&mut self, block: &DeclarationBlock) {
        self.out.push_str(" {");
        if self.minify {
            self.declaration_block_inner(block);
        } else {
        self.out.push('\\n');""")
s=s.replace("""            self.indent += 1;
            self.out.push_str(&self.indent_str());
            self.declaration_block_inner(block);
            self.indent -= 1;
            self.newline();
        }
        self.out.push('}');
    }

    fn declaration_block_inner""","""            self.indent += 1;
            self.out.push_str(&self.indent_str());
            self.declaration_block_inner(block);
            self.indent -= 1;
            self.newline();
        }
        }
        self.out.push('}');
    }

    fn declaration_block_inner""")
open('src/printer.rs','w').write(s)

s=open('src/minify_values.rs').read()
s=s.replace("""        Value::Number(n) => {
            n.unit = shorten_unit(&n.unit);
        }
        Value::Color(c) => {
            convert_color(c);
        }
        Value::List(items) | Value::CommaList(items) => {
            for it in items.iter_mut() {
                minify_component(it);
            }
        }
        _ => {}
    }
}""","""        Value::Number(n) => {
            if n.value == 0.0 && n.unit.as_deref() == Some("px") {
                n.unit = None;
            }
        }
        Value::Color(c) => {
            convert_color(c);
        }
        Value::List(items) | Value::CommaList(items) => {
            for it in items.iter_mut() {
                minify_component(it);
            }
        }
        _ => {}
    }
}""")
s=s.replace("""fn minify_component(v: &mut Value) {
    match v {
        Value::Number(n) => {
            n.unit = shorten_unit(&n.unit);
        }""","""fn minify_component(v: &mut Value) {
    match v {
        Value::Number(n) => {
            if n.value == 0.0 && n.unit.as_deref() == Some("px") {
                n.unit = None;
            }
        }""")
open('src/minify_values.rs','w').write(s)
print('ok')
