new = '''    /// Parse a property value into a raw token list with typed values embedded.
    fn parse_property_value(&mut self, _property: &str) -> Result<Value, Error> {
        let raw = self.parse_value_list('\\0');
        Ok(Value::Raw(raw))
    }

    /// Parse `!important` if present.
    fn parse_important(&mut self) -> bool {
        let save_pos = self.tok.position();
        self.skip_ws();
        if self.cur == Token::Delim('!') {
            self.bump();
            self.skip_ws();
            if let Token::Ident(name) = self.cur.clone() {
                if name.eq_ignore_ascii_case("important") {
                    self.bump();
                    return true;
                }
            }
        }
        self.restore((save_pos, self.cur.clone(), self.cur_start, self.cur_end));
        false
    }

    fn consume_semicolon(&mut self) {
        self.skip_ws();
        if self.cur == Token::Semicolon {
            self.bump();
        }
    }

    /// Parse tokens into raw items, stopping at the given close character.
    /// `close` is one of ')', ']', '}', or '\\0' for the top level.
    fn parse_value_list(&mut self, close: char) -> Vec<RawTok> {
        let mut out: Vec<RawTok> = Vec::new();
        loop {
            match self.cur.clone() {
                Token::EOF => break,
                Token::Semicolon if close == '\\0' => break,
                Token::CloseCurlyBracket if close == '\\0' => break,
                Token::CloseParenthesis if close == ')' => break,
                Token::CloseSquareBracket if close == ']' => break,
                Token::CloseCurlyBracket if close == '}' => break,
                Token::OpenCurlyBracket => {
                    out.push(RawTok::Text("{".to_string()));
                    self.bump();
                    let inner = crate::parser::trim_raw(self.parse_value_list('}'));
                    out.extend(inner);
                    if self.cur == Token::CloseCurlyBracket {
                        out.push(RawTok::Text("}".to_string()));
                        self.bump();
                    }
                }
                Token::OpenParenthesis => {
                    out.push(RawTok::Text("(".to_string()));
                    self.bump();
                    let inner = crate::parser::trim_raw(self.parse_value_list(')'));
                    out.extend(inner);
                    if self.cur == Token::CloseParenthesis {
                        out.push(RawTok::Text(")".to_string()));
                        self.bump();
                    }
                }
                Token::OpenSquareBracket => {
                    out.push(RawTok::Text("[".to_string()));
                    self.bump();
                    let inner = crate::parser::trim_raw(self.parse_value_list(']'));
                    out.extend(inner);
                    if self.cur == Token::CloseSquareBracket {
                        out.push(RawTok::Text("]".to_string()));
                        self.bump();
                    }
                }
                Token::CloseParenthesis | Token::CloseSquareBracket | Token::CloseCurlyBracket => {
                    out.push(RawTok::Text(self.text()));
                    self.bump();
                }
                Token::Function(name) => {
                    let name = name.to_string();
                    self.bump();
                    self.parse_value_function(&name, &mut out);
                }
                Token::UnquotedUrl(_) => {
                    let start = self.cur_start;
                    self.bump();
                    let text = &self.src[start..self.cur_end];
                    let inner = text
                        .trim_start_matches("url(")
                        .trim_end_matches(')')
                        .trim();
                    out.push(RawTok::Val(Box::new(Value::Url(Some(inner.to_string())))));
                }
                Token::Number {
                    value,
                    int_value,
                    ..
                } => {
                    self.bump();
                    out.push(RawTok::Val(Box::new(Value::Number(Number {
                        value,
                        int_value,
                        unit: None,
                    }))));
                }
                Token::Percentage {
                    value,
                    int_value,
                    ..
                } => {
                    self.bump();
                    out.push(RawTok::Val(Box::new(Value::Number(Number {
                        value,
                        int_value,
                        unit: Some("%".to_string()),
                    }))));
                }
                Token::Dimension {
                    value,
                    int_value,
                    unit,
                    ..
                } => {
                    self.bump();
                    out.push(RawTok::Val(Box::new(Value::Number(Number {
                        value,
                        int_value,
                        unit: Some(unit.to_string()),
                    }))));
                }
                Token::Str(s) => {
                    self.bump();
                    out.push(RawTok::Val(Box::new(Value::Str(s.to_string()))));
                }
                Token::Hash { value, .. } => {
                    self.bump();
                    match parse_hex(value) {
                        Some((r, g, b, a)) => {
                            out.push(RawTok::Val(Box::new(Value::Color(Color::Rgba(r, g, b, a)))))
                        }
                        None => out.push(RawTok::Text(format!("#{}", value))),
                    }
                }
                Token::Comment(c) => {
                    let t = format!("/*{}*/", c);
                    self.bump();
                    out.push(RawTok::Text(t));
                }
                Token::WhiteSpace => {
                    let t = self.text();
                    self.bump();
                    out.push(RawTok::Text(t));
                }
                _ => {
                    let t = self.text();
                    self.bump();
                    out.push(RawTok::Text(t));
                }
            }
        }
        out
    }

    /// Parse a function call inside a value.
    fn parse_value_function(&mut self, name: &str, out: &mut Vec<RawTok>) {
        match name {
            "var" => {
                self.skip_ws();
                let custom = match self.cur.clone() {
                    Token::Ident(n) if n.starts_with("--") => {
                        self.bump();
                        n.to_string()
                    }
                    _ => {
                        out.push(RawTok::Text(format!("var(")));
                        let inner = crate::parser::trim_raw(self.parse_value_list(')'));
                        out.extend(inner);
                        if self.cur == Token::CloseParenthesis {
                            out.push(RawTok::Text(")".to_string()));
                            self.bump();
                        }
                        return;
                    }
                };
