                    self.bump();
                    let items = self.parse_value_list('\\0');
                    fallback = Some(crate::parser::trim_raw(items));
                }
                if self.cur == Token::CloseParenthesis {
                    self.bump();
                }
                out.push(RawTok::Val(Box::new(Value::Var { name: custom, fallback })));
