            "url" => {
                self.skip_ws();
                let inner = crate::parser::trim_raw(self.parse_value_list(')'));
                if self.cur == Token::CloseParenthesis {
                    self.bump();
                }
                // url(<string>) or url()
                if inner.len() == 1 {
                    if let RawTok::Val(v) = &inner[0] {
                        if let Value::Str(s) = &**v {
                            out.push(RawTok::Val(Box::new(Value::Url(Some(s.clone())))));
                            return;
                        }
                    }
                }
                if inner.is_empty() {
                    out.push(RawTok::Val(Box::new(Value::Url(Some(String::new())))));
                    return;
                }
                out.push(RawTok::Text("url(".to_string()));
                out.extend(inner);
                out.push(RawTok::Text(")".to_string()));
            }
            "rgb" | "rgba" | "hsl" | "hsla" | "hwb" | "color" | "color-mix" => {
                self.skip_ws();
                let items = self.parse_value_list(')');
                if self.cur == Token::CloseParenthesis {
                    self.bump();
                }
                match try_parse_color_function(name, &items) {
