                    None => {
                        out.push(RawTok::Text(format!("{}(", name)));
                        out.extend(crate::parser::trim_raw(items));
                        out.push(RawTok::Text(")".to_string()));
                    }
                }
            }
            _ => {
                out.push(RawTok::Text(format!("{}(", name)));
                let items = crate::parser::trim_raw(self.parse_value_list(')'));
                out.extend(items);
                if self.cur == Token::CloseParenthesis {
                    out.push(RawTok::Text(")".to_string()));
                    self.bump();
                }
            }
