}

/// Remove leading and trailing whitespace items from a raw list.
pub fn trim_raw(mut items: Vec<RawTok>) -> Vec<RawTok> {
    while matches!(items.first(), Some(RawTok::Text(t)) if t.chars().all(|c| c == ' ' || c == '\\t' || c == '\\n' || c == '\\r' || c == '\\x0c')) {
        items.remove(0);
    }
    while matches!(items.last(), Some(RawTok::Text(t)) if t.chars().all(|c| c == ' ' || c == '\\t' || c == '\\n' || c == '\\r' || c == '\\x0c')) {
        items.pop();
    }
    items
}

/// Try to interpret a raw color function argument list as a color.
fn try_parse_color_function(name: &str, items: &[RawTok]) -> Option<Color> {
    // Convert the raw items to a comma list of values, ignoring whitespace.
    let mut args: Vec<Value> = Vec::new();
    let mut cur: Vec<Value> = Vec::new();
    for it in items {
        match it {
            RawTok::Val(v) => cur.push((**v).clone()),
            RawTok::Text(t) => {
                let tt = t.trim();
                if tt.is_empty() {
                    continue;
                }
                if tt == "," {
                    if !cur.is_empty() {
                        args.push(if cur.len() == 1 {
                            cur.pop().unwrap()
                        } else {
                            Value::List(cur.drain(..).collect())
                        });
                    }
                    continue;
                }
                // try to parse the text as a number or ident
                if let Some(v) = crate::parser::parse_value_text(tt) {
                    cur.push(v);
                } else {
                    cur.push(Value::Ident(tt.to_string()));
                }
            }
        }
    }
    if !cur.is_empty() {
        args.push(if cur.len() == 1 {
            cur.pop().unwrap()
        } else {
            Value::List(cur.drain(..).collect())
        });
    }
    parse_color_function(name, &args)
}

/// Parse a simple text token into a value if it is a number or percentage.
pub fn parse_value_text(t: &str) -> Option<Value> {
    let mut chars = t.chars();
    let mut rest = t;
    let mut sign = 1.0;
    let first = chars.next()?;
    if first == '-' || first == '+' {
        if first == '-' {
            sign = -1.0;
        }
        rest = &t[1..];
    }
    if rest.is_empty() {
        return None;
    }
    // percentage?
    if let Some(num) = rest.strip_suffix('%') {
        if let Ok(v) = num.parse::<f32>() {
            return Some(Value::Number(Number {
                value: sign * v,
                int_value: None,
                unit: Some("%".to_string()),
            }));
        }
        return None;
    }
    // number with optional exponent
    let (mant, exp) = match rest.find(|c| c == 'e' || c == 'E') {
        Some(i) => (&rest[..i], Some(&rest[i + 1..])),
        None => (rest, None),
    };
    let (ip, fp) = match mant.find('.') {
        Some(i) => (&mant[..i], Some(&mant[i + 1..])),
        None => (mant, None),
    };
    if ip.is_empty() && fp.map(|f| f.is_empty()).unwrap_or(true) {
        return None;
    }
    for c in ip.chars() {
        if !c.is_ascii_digit() {
            return None;
        }
    }
    if let Some(f) = fp {
        if f.is_empty() {
            return None;
        }
        for c in f.chars() {
            if !c.is_ascii_digit() {
                return None;
            }
        }
    }
    if let Some(e) = exp {
        let mut ec = e.chars();
        if let Some(c) = ec.next() {
            if c == '+' || c == '-' {
                ec.next();
            }
        }
        if ec.as_str().is_empty() {
            return None;
        }
        for c in ec.as_str().chars() {
            if !c.is_ascii_digit() {
                return None;
            }
        }
    }
    let value: f32 = t.parse().ok()?;
    if value.is_infinite() {
        return None;
    }
    let int_value = if fp.is_none() && exp.is_none() {
        t.trim_start_matches('+').parse::<i32>().ok()
    } else {
        None
    };
    Some(Value::Number(Number {
        value,
        int_value,
        unit: None,
    }))
}
