new='''fn parse_color_mix(args: &[crate::ast::Value]) -> Option<Color> {
    // color-mix(in <space>, <color> [pct], <color> [pct])
    let mut flat: Vec<crate::ast::Value> = Vec::new();
    for a in args {
        match a {
            crate::ast::Value::List(v) | crate::ast::Value::CommaList(v) => {
                flat.extend(v.iter().cloned())
            }
            other => flat.push(other.clone()),
        }
    }
    // find "in"
    let mut idx = 0;
    let mut space: Option<String> = None;
    while idx < flat.len() {
        if let crate::ast::Value::Ident(i) = &flat[idx] {
            if i == "in" {
                // the space name follows
                let mut names = Vec::new();
                let mut j = idx + 1;
                while j < flat.len() {
                    if let crate::ast::Value::Ident(n) = &flat[j] {
                        names.push(n.clone());
                        j += 1;
                    } else {
                        break;
                    }
                }
                if !names.is_empty() {
                    space = Some(names.join(" "));
                }
                idx = j;
                break;
            }
        }
        idx += 1;
    }
    let mut rest: Vec<crate::ast::Value> = flat[idx..].to_vec();
    if rest.len() < 2 {
        return None;
    }
    let c1 = value_to_color(&rest[0])?;
    let mut pct1 = None;
    let mut i2 = 1;
    if let crate::ast::Value::Number(n) = &rest[1] {
        if n.unit.as_deref() == Some("%") {
            pct1 = Some(n.value / 100.0);
            i2 = 2;
        }
    }
    if i2 >= rest.len() {
        return None;
    }
    let c2 = value_to_color(&rest[i2])?;
    let mut pct2 = None;
    if let Some(crate::ast::Value::Number(n)) = rest.get(i2 + 1) {
        if n.unit.as_deref() == Some("%") {
            pct2 = Some(n.value / 100.0);
        }
    }
    Some(Color::Mix(Box::new(ColorMix {
        color1: c1,
        pct1,
        color2: c2,
        pct2,
        space,
    })))
}

