for a,b,s in pairs:
    if s==1: lt.setdefault(a,set()).add(b); gt.setdefault(b,set()).add(a)
    else: gt.setdefault(a,set()).add(b); lt.setdefault(b,set()).add(a)
def viol(order):
    idx={p:i for i,p in enumerate(order)}
    n=0
    for a,b,s in pairs:
        if (idx[a]<idx[b]) != (s==1): n+=1
    return n
order=props[:]
best=viol(order)
print('start',best, flush=True)
random.seed(7)
import time
t0=time.time()
while time.time()-t0 < 600:
