//! lightningcss CLI entry point.

mod ast;
mod cli;
mod colors;
mod colors_data;
mod error;
mod minify;
mod minify_values;
mod parser;
mod printer;
mod props_data;
mod properties;
mod sourcemap;
mod token;
mod values;

use std::io::Read;
use std::io::Write;
use std::path::Path;

/// A single unit of work: one input file together with its options.
pub struct Job {
    /// The name reported in error messages and source maps.
    pub filename: String,
    /// The raw source text.
    pub source: String,
    /// The index of this input within the invocation.
    pub index: usize,
}

/// The result of transforming one input.
pub struct Output {
    pub name: String,
    pub code: String,
    pub map: Option<sourcemap::SourceMap>,
}

/// Read the contents of an input file.
///
/// The path is resolved relative to the current working directory. A missing or
/// unreadable file results in a resolver error, which is reported as a panic
/// just like the original implementation does.
fn read_source(path: &Path, idx: usize) -> String {
    let _ = idx;
    std::fs::read_to_string(path).unwrap()
}

/// Parse a stylesheet from `src`.
///
/// `o` selects the parser options (custom media queries, error recovery) and
/// carries the file name used in diagnostics. `ix` is the index of the input
/// within the current invocation.
fn parse(src: &str, o: &cli::Options, ix: usize) -> crate::ast::Stylesheet {
    let _ = ix;
    let filename = o.filename_for(ix);
    let mut p = crate::parser::Parser::new(src, &filename, o.custom_media, o.error_recovery);
    let sheet = p.parse_stylesheet();
    match sheet {
        Ok(s) => s,
        Err(e) => {
            if o.error_recovery {
                for msg in p.errors.iter() {
                    eprintln!("{}", msg);
                }
                crate::ast::Stylesheet::default()
            } else {
                panic_with(e)
            }
        }
    }
}

/// Abort the process the same way an unwrapped `Result` would.
fn panic_with(e: crate::error::Error) -> ! {
    let msg = format!(
        "called `Result::unwrap()` on an `Err` value: {:?}",
        e
    );
    eprintln!(
        "\nthread 'main' ({}) panicked at src/main.rs:187:45:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
        std::process::id(),
        msg
    );
    std::process::abort()
}

/// Abort with a resolver error (no location information).
fn panic_resolver(e: &str) -> ! {
    let kind = crate::error::ErrorKind::ResolverError(e.to_string());
    let msg = format!(
        "called `Result::unwrap()` on an `Err` value: {:?}",
        crate::error::Error {
            kind,
            loc: None
        }
    );
    eprintln!(
        "\nthread 'main' ({}) panicked at src/main.rs:180:46:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
        std::process::id(),
        msg
    );
    std::process::abort()
}

/// Transform a single input.
fn run(job: &Job, opts: &cli::Options) -> Output {
    let sheet = parse(&job.source, opts, job.index);
    let mut sheet = sheet;
    crate::minify::minify(&mut sheet, opts.minify);
    let mut printer = crate::printer::Printer::new(opts.minify);
    printer.stylesheet(&sheet);
    let code = printer.out;
    let map = if opts.sourcemap {
        Some(crate::sourcemap::generate(&job.filename, &job.source, &code))
    } else {
        None
    };
    Output {
        name: job.name.clone(),
        code,
        map,
