head = '''//! lightningcss CLI entry point.
//!
//! This module wires the command line interface to the CSS parser and
//! serializer.  The pipeline is:
//!
//! 1. read the input, either from the files given on the command line or from
//!    standard input;
//! 2. parse it into a stylesheet;
//! 3. apply the transformation passes;
//! 4. serialize the result;
//! 5. write it to the requested destination.
//!
//! Parse errors abort the process, mirroring the behaviour of unwrapping the
//! parser result.

mod ast;
mod cli;
mod colors;
mod colors_data;
mod error;
mod minify;
mod minify_values;
mod parser;
mod printer;
mod props_data;
mod properties;
mod sourcemap;
mod token;
mod values;

use std::io::Read;
use std::io::Write;
use std::path::Path;

/// A single unit of work: one input file together with its options.
pub struct Job {
    /// The name reported in error messages and source maps.
    pub filename: String,
    /// The base name used for the output file.
    pub name: String,
    /// The raw source text.
    pub source: String,
    /// The index of this input within the invocation.
    pub index: usize,
}

/// The result of transforming one input.
pub struct Output {
    pub name: String,
    pub code: String,
    pub map: Option<sourcemap::SourceMap>,
}

/// Abort the process the same way an unwrapped `Result` would.
fn panic_with(e: crate::error::Error) -> ! {
    let msg = format!("called `Result::unwrap()` on an `Err` value: {:?}", e);
    eprintln!(
        "\\nthread 'main' ({}) panicked at src/main.rs:187:45:\\n{}\\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
        std::process::id(),
        msg
    );
    std::process::abort()
}

/// Abort with a resolver error (no location information is available).
fn panic_resolver(e: &str) -> ! {
    let err = crate::error::Error {
        kind: crate::error::ErrorKind::ResolverError(e.to_string()),
        loc: None,
    };
    let msg = format!("called `Result::unwrap()` on an `Err` value: {:?}", err);
    eprintln!(
        "\\nthread 'main' ({}) panicked at src/main.rs:180:46:\\n{}\\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
        std::process::id(),
        msg
    );
    std::process::abort()
}

/// Report the diagnostics collected by the parser in error recovery mode.
fn report_errors(p: &crate::parser::Parser) {
    for msg in p.errors.iter() {
        eprintln!("{}", msg);
    }
}

/// Parse a stylesheet from `src`.
///
/// `o` selects the parser options and carries the file name used in
/// diagnostics.  `ix` is the index of the input within the invocation.
fn parse(src: &str, o: &cli::Options, ix: usize) -> crate::ast::Stylesheet {
    let _ = ix;
    let filename = o.filename_for(ix);
    let mut p = crate::parser::Parser::new(src, &filename, o.custom_media, o.error_recovery);
    match p.parse_stylesheet() {
        Ok(s) => s,
        Err(e) => {
            report_errors(&p);
            if o.error_recovery {
                crate::ast::Stylesheet::default()
            } else {
                panic_with(e)
            }
        }
    }
}

/// Read the contents of an input file, reporting a resolver error on failure.
fn read_source(path: &Path, idx: usize) -> Result<String, std::io::Error> {
    let _ = idx;
    std::fs::read_to_string(path)
}

/// Read all inputs, either from the given files or from standard input.
fn read_inputs(opts: &cli::Options) -> Vec<Job> {
    let mut jobs: Vec<Job> = Vec::new();
    if opts.inputs.is_empty() {
        let mut buf = String::new();
        std::io::stdin().read_to_string(&mut buf).unwrap();
        let filename = format!("stdin-{}", std::process::id());
        jobs.push(Job {
            filename: filename.clone(),
            name: filename,
            source: buf,
            index: 0,
        });
    } else {
        for (idx, input) in opts.inputs.iter().enumerate() {
            let path = Path::new(input);
            let canonical = std::fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
            let filename = crate::cli::relative_to_cwd(&canonical);
            let name = path
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| input.clone());
            let src = read_source(path, idx).unwrap();
            jobs.push(Job { filename, name, source: src, index: idx });
        }
    }
    jobs
}
