/// `o` selects the parser options and carries the file name used in
/// diagnostics.  `ix` is the index of the input within the invocation.
fn parse(src: &str, o: &cli::Options, ix: usize) -> crate::ast::Stylesheet {
    let _ = ix;
    let filename = o.filename_for(ix);
    let mut p = crate::parser::Parser::new(src, &filename, o.custom_media, o.error_recovery);
    match p.parse_stylesheet() {
        Ok(s) => s,
        Err(e) => {
            report_errors(&p);
            if o.error_recovery {
                crate::ast::Stylesheet::default()
            } else {
                panic_with(e)
            }
        }
    }
