    crate::minify::minify(&mut stylesheet, o.minify);
    let mut printer = crate::printer::Printer::new(o.minify);
    printer.stylesheet(&stylesheet);
    let code = printer.out;
    let map = if o.sourcemap {
        Some(crate::sourcemap::generate(&job.filename, src, &code))
    } else {
        None
    };
    Output {
        name: job.name.clone(),
        code,
        map,
    }
}

fn main() {
    let argv: Vec<String> = std::env::args().collect();
    let bin = argv
        .first()
        .map(|s| {
            Path::new(s)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| s.clone())
        })
        .unwrap_or_else(|| "lightningcss".to_string());
    let args: Vec<String> = argv.iter().skip(1).cloned().collect();
    let opts = match crate::cli::parse_args(&args, &bin) {
        crate::cli::ParseResult::Printed(s) => {
            print!("{}", s);
            std::process::exit(0);
        }
        crate::cli::ParseResult::Err(msg, code) => {
            eprint!("{}", msg);
            std::process::exit(code);
        }
        crate::cli::ParseResult::Ok(o) => o,
    };

    if opts.inputs.len() > 1 && opts.output_file.is_some() {
        eprintln!(
            "Cannot use the --output-file option with multiple inputs. Use --output-dir instead."
        );
        std::process::exit(1);
    }
    if opts.inputs.len() > 1 && opts.output_file.is_none() && opts.output_dir.is_none() {
        eprintln!("Cannot output to stdout with multiple inputs. Use --output-dir instead.");
        std::process::exit(1);
    }

    let inputs = read_inputs(&opts);
    let mut outputs: Vec<Output> = Vec::new();
    for job in &inputs {
        outputs.push(run(&job.source, &opts, job.index, job));
    }

    if let Some(dir) = &opts.output_dir {
        std::fs::create_dir_all(dir).unwrap();
        for out in &outputs {
            let out_path = Path::new(dir).join(&out.name);
            let data = match &out.map {
                Some(m) => format!(
                    "{}/*# sourceMappingURL={}.map */\n",
                    out.code,
                    out_path.to_string_lossy()
                ),
                None => out.code.clone(),
            };
            std::fs::write(&out_path, data).unwrap();
            if let Some(m) = &out.map {
                let mp = format!("{}.map", out_path.to_string_lossy());
                std::fs::write(mp, m.to_json()).unwrap();
            }
        }
        return;
    }

    if let Some(out_file) = &opts.output_file {
        let out = &outputs[0];
        let data = match &out.map {
            Some(_) => format!("{}/*# sourceMappingURL={}.map */\n", out.code, out_file),
            None => out.code.clone(),
        };
        std::fs::write(out_file, data).unwrap();
        if let Some(m) = &out.map {
            std::fs::write(format!("{}.map", out_file), m.to_json()).unwrap();
        }
        return;
    }

    if let Some(css_modules) = &opts.css_modules {
        let out = &outputs[0];
        let exports = crate::minify::css_modules_exports(&out.code);
        let obj = crate::minify::css_modules_json(&out.code, &exports);
        match css_modules {
            Some(file) => {
                std::fs::write(file, obj).unwrap();
                print!("{}", out.code);
            }
            None => print!("{}", obj),
        }
        return;
    }

    for out in &outputs {
        print!("{}", out.code);
    }
}
