impl Options {
    /// The file name used for diagnostics of input `ix`.
    pub fn filename_for(&self, ix: usize) -> String {
        if self.inputs.is_empty() {
            format!("stdin-{}", std::process::id())
        } else {
            self.inputs
                .get(ix)
                .cloned()
                .unwrap_or_default()
        }
    }
}

/// Build a path relative to the current working directory.
pub fn relative_to_cwd(path: &std::path::Path) -> String {
    let cwd = std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("."));
    match path.strip_prefix(&cwd) {
        Ok(p) => p.to_string_lossy().to_string(),
        Err(_) => {
            let cwd_comps: Vec<_> = cwd.components().collect();
            let p_comps: Vec<_> = path.components().collect();
            let mut common = 0;
            while common < cwd_comps.len()
                && common < p_comps.len()
                && cwd_comps[common] == p_comps[common]
            {
                common += 1;
            }
            let mut parts: Vec<String> = Vec::new();
            for _ in common..cwd_comps.len() {
                parts.push("..".to_string());
            }
            for c in &p_comps[common..] {
                parts.push(c.as_os_str().to_string_lossy().to_string());
            }
            parts.join("/")
        }
    }
}
